static std::string format_int(int value) {
    char digits[16];
    std::size_t count = 0;
    const bool negative = value < 0;
    unsigned int magnitude = negative ? static_cast<unsigned int>(-(value + 1)) + 1u : static_cast<unsigned int>(value);
    do { digits[count++] = static_cast<char>('0' + (magnitude % 10u)); magnitude /= 10u; } while (magnitude != 0u);
    std::string result;
    result.reserve(count + (negative ? 1u : 0u));
    if (negative) result.push_back('-');
    while (count > 0) result.push_back(digits[--count]);
    return result;
}

static std::string decode_base64(std::string_view encoded) {
    auto digit = [](unsigned char c) -> int {
        if (c >= 'A' && c <= 'Z') return static_cast<int>(c - 'A');
        if (c >= 'a' && c <= 'z') return static_cast<int>(c - 'a') + 26;
        if (c >= '0' && c <= '9') return static_cast<int>(c - '0') + 52;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return -1;
    };
    std::string decoded;
    decoded.reserve((encoded.size() / 4u) * 3u);
    std::uint32_t bits_value = 0;
    int bit_count = 0;
    for (unsigned char c : encoded) {
        if (c == '=') break;
        const int value = digit(c);
        if (value < 0) continue;
        bits_value = (bits_value << 6u) | static_cast<std::uint32_t>(value);
        bit_count += 6;
        if (bit_count >= 8) {
            bit_count -= 8;
            decoded.push_back(static_cast<char>((bits_value >> bit_count) & 0xffu));
        }
    }
    return decoded;
}

