static const char *localized_texture_label(int texture, int mission, int slot, int language) {
    const int lang = rendered_language(language);
    int special = -1;
    if (mission == 8 && slot == 0 && texture == 20) special = 0;
    else if (mission == 7 && texture == 22) special = 1;
    else if (mission == 0 && texture == 22) special = 2;
    else if (mission == 11 && texture == 3) special = 4;
    else if (mission == 4 && texture == 21) special = 5;
    if (special >= 0) return kTextureSpecials[lang][special];
    if (texture >= 16 && texture <= 24) return kAdditionalTextureLabels[lang][texture - 16];
    if (texture >= 7 && texture <= 15) return kUtilityTextureLabels[lang][texture - 7];
    const int index = texture >= 1 && texture <= 6 ? texture : 0;
    return kTextureLabels[lang][index];
}

class GeneratedScreen final : public hui::app::Concept {
public:
    explicit GeneratedScreen(hui::app::Context &context) : context_(context) {}

    const hui::app::ConceptInfo &info() const override {
        static constexpr const char *kTechniques[] = {
            "Lavadora nativa interactiva basada en la web original",
            "Animación del tambor, agua, puerta, cajón y ciclo de lavado",
            "Efectos de sonido desde el mezclador integrado del IDE",
            "Glifos vectoriales del DualSense: no depende de caracteres Unicode de botón",
            "20 misiones originales y 5 misiones expertas basadas en la Girbau HS-6008 / LOGI PRO CONTROL"
        };
        static const hui::app::ConceptInfo kInfo{
            "taller-colada", "Taller de Colada", "Simulador interactivo de lavadora con modo normal y modo experto",
            "generated/ps5hs-screen.cpp", hui::audio::SoundSet::glass,
            Color::rgb(0x2a9bc0), kTechniques
        };
        return kInfo;
    }

    void enter() override {
        screen_ = Screen::title;
        previous_screen_ = Screen::title;
        selected_mission_ = 0;
        title_selection_ = 0;
        settings_selection_ = 0;
        saves_selection_ = 0;
        dialog_selection_ = 1;
        focus_id_ = 0;
        age_ = 0.0f;
        clock_ = 0.0f;
        errors_ = 0;
        hints_ = 0;
        simulation_active_ = false;
        simulation_manual_view_ = false;
        simulation_fault_mask_ = 0;
        simulation_manual_read_mask_ = 0;
        simulation_case_number_ = 0;
        simulation_leak_secured_ = false;
        simulation_manual_page_elapsed_ = 0.0f;
        load_settings_from_disk();
        inspect_saved_game();
        title_selection_ = (save_exists_ || any_progress()) ? 0 : 1;
        care_label_open_ = false;
        care_label_slot_ = 0;
        message_ = ui_text(UiText::initial_hint);
        message_kind_ = 0;
        load_textures();
    }

    void update(const hui::InputFrame &input, float dt, hui::app::Feedback &feedback) override {
        if (input.focus_lost) {
            stick_direction_ = Direction::none;
            stick_repeat_timer_ = 0.0f;
            return;
        }
        dt = std::max(0.0f, std::min(dt, 0.1f));
        clock_ += dt;
        age_ += dt;
        if (screen_ == Screen::manual && simulation_manual_view_ && simulation_active_) {
            simulation_manual_page_elapsed_ += dt;
            if (simulation_manual_page_elapsed_ >= 1.25f && manual_page_ >= 0 && manual_page_ < kSimulationManualPageCount)
                simulation_manual_read_mask_ |= static_cast<std::uint8_t>(1u << static_cast<unsigned int>(manual_page_));
        }
        door_anim_ = approach(door_anim_, door_open_ ? 1.0f : 0.0f, dt * 3.8f);
        drawer_anim_ = approach(drawer_anim_, drawer_open_ ? 1.0f : 0.0f, dt * 5.5f);
        focus_pulse_ += dt;
        enforce_power_invariant(true);
        if (!care_label_open_) update_cycle(dt);
        if (screen_ == Screen::play && running_ && !care_label_open_ && !simulation_active_) progress_dirty_ = true;
        if (screen_ == Screen::play && care_label_open_) {
            if (input.is_pressed(hui::Action::back) || input.is_pressed(hui::Action::confirm) || input.is_pressed(hui::Action::r3)) {
                care_label_open_ = false; queue_sound(hui::audio::Cue::modal_close);
            } else if (input.nav == hui::Direction::left || input.nav == hui::Direction::right) {
                move_care_label_slot(input.nav == hui::Direction::right ? 1 : -1);
            }
            if (pending_sound_) { feedback.play(pending_cue_, 1.0f, 0.0f, static_cast<float>(effects_volume_) / 100.0f); pending_sound_ = false; }
            return;
        }
        handle_stick(input, dt);
        if (!input.nav_from_stick && input.nav != hui::Direction::none)
            handle_navigation(convert_direction(input.nav));
        if (input.is_pressed(hui::Action::back)) {
            if (adjusting_) { adjusting_ = false; queue_sound(hui::audio::Cue::back); }
            else go_back();
        }
        if (input.is_pressed(hui::Action::menu) && screen_ == Screen::play) {
            service_open_ = !service_open_;
            focus_id_ = service_open_ ? 18 : 17;
            queue_sound(service_open_ ? hui::audio::Cue::open : hui::audio::Cue::modal_close);
            set_message(service_open_ ? ui_text(UiText::msg_service_open_safe) : ui_text(UiText::msg_service_closed), 0);
        }
        if (input.is_pressed(hui::Action::north)) {
            if (screen_ == Screen::manual) { screen_ = previous_screen_; simulation_manual_view_ = false; queue_sound(hui::audio::Cue::modal_close); }
            else { simulation_manual_view_ = simulation_active_ || screen_ == Screen::simulation; previous_screen_ = screen_; screen_ = Screen::manual; manual_page_ = 0; simulation_manual_page_elapsed_ = 0.0f; queue_sound(hui::audio::Cue::modal_open); }
        }
        if (screen_ == Screen::missions && all_missions_complete() && input.is_pressed(hui::Action::west)) {
            // Square is forwarded by the upstream shell; L1/R1 are intercepted globally.
            switch_mission_mode(!expert_mode_view_);
        } else if (input.is_pressed(hui::Action::west)) {
            if (!simulation_active_) show_hint();
        }
        // R3 is forwarded to the concept. The shell consumes touchpad clicks for its own info panel.
        if (screen_ == Screen::play && input.is_pressed(hui::Action::r3)) open_care_label();
        if (input.is_pressed(hui::Action::confirm)) {
            if (screen_ == Screen::play && !simulation_active_) progress_dirty_ = true;
            activate();
        }
        if (pending_sound_) {
            feedback.play(pending_cue_, 1.0f, 0.0f, static_cast<float>(effects_volume_) / 100.0f);
            pending_sound_ = false;
        }
        if (screen_ == Screen::play && autosave_ && input.is_pressed(hui::Action::confirm) && !simulation_active_) save_progress(true);
    }

    void draw(hui::app::Frame &frame) const override {
        ensure_language_fallbacks();
        DrawList &draw = frame.scene;
        draw.clear();
        draw.gradient_rect(Rect{0,0,1920,1080}, 0, Color::rgb(0xf3f8fb), Color::rgb(0xdceaf2));
        // Keep the background full-screen, but scale the entire interface within a centred 16:9 safe area.
        draw.push_transform(static_cast<float>(ui_scale_)/100.0f,960.0f,540.0f,0.0f,0.0f);
        draw_background_bubbles(draw);
        draw_top_bar(draw);
        switch (screen_) {
            case Screen::title: draw_title(draw); break;
            case Screen::missions: draw_menu(draw); break;
            case Screen::play: draw_play(draw); break;
            case Screen::result: draw_play(draw); draw_result(draw); break;
            case Screen::simulation: draw_simulation_menu(draw); break;
            case Screen::manual: if (previous_screen_ == Screen::play || previous_screen_ == Screen::result) draw_play(draw); else draw_title_backdrop(draw); draw_manual(draw); break;
            case Screen::settings: draw_settings(draw); break;
            case Screen::saves: draw_saves(draw); break;
            case Screen::confirm_delete: draw_saves(draw); draw_confirmation(draw); break;
            case Screen::confirm_new_game: draw_title(draw); draw_confirmation(draw); break;
        }
        draw_footer(draw);
        draw.pop_transform();
        draw_display_adjustments(draw);
    }

