    static float approach(float value, float target, float amount) {
        if (value < target) return std::min(target, value + amount);
        return std::max(target, value - amount);
    }
    static float clamp01(float value) { return std::max(0.0f, std::min(1.0f, value)); }
    static int clamp_int(int v, int lo, int hi) { return std::max(lo, std::min(v, hi)); }
    static Direction convert_direction(hui::Direction d) {
        switch (d) {
            case hui::Direction::up: return Direction::up;
            case hui::Direction::down: return Direction::down;
            case hui::Direction::left: return Direction::left;
            case hui::Direction::right: return Direction::right;
            default: return Direction::none;
        }
    }
    void queue_sound(hui::audio::Cue cue) { if (effects_volume_ <= 0) { pending_sound_ = false; return; } pending_cue_ = cue; pending_sound_ = true; }
    bool is_expert_mission(int index) const { return index >= kMissionCount && index < kTotalMissionCount; }
    int expert_index(int index) const { return clamp_int(index - kMissionCount, 0, kExpertMissionCount - 1); }
    const Mission &mission_definition(int index) const { return is_expert_mission(index) ? kExpertMissions[expert_index(index)] : kMissions[clamp_int(index, 0, kMissionCount - 1)]; }
    const Mission &mission() const { return mission_definition(selected_mission_); }
    const char *ui_text(UiText key) const { return kUiStrings[rendered_language(language_)][static_cast<std::size_t>(key)]; }
    const char *sim_text(SimText key) const { return kSimulationUiStrings[rendered_language(language_)][static_cast<std::size_t>(key)]; }
    const char *expert_text(ExpertUiText key) const { return kExpertUiStrings[rendered_language(language_)][static_cast<std::size_t>(key)]; }
    static constexpr std::uint8_t simulation_fault_bit(SimulationFault fault) { return static_cast<std::uint8_t>(1u << static_cast<unsigned int>(fault)); }
    bool simulation_has_fault(SimulationFault fault) const { return (simulation_fault_mask_ & simulation_fault_bit(fault)) != 0u; }
    const char *simulation_alarm_code(int fault) const {
        static constexpr const char *codes[kSimulationFaultCount]={"ALM/A-*","ALM/E","END/BAL","ALM/door","ALM/L"};
        return codes[static_cast<std::size_t>(clamp_int(fault,0,kSimulationFaultCount-1))];
    }
    int simulation_fault_manual_page(SimulationFault fault) const {
        switch (fault) {
            case SimulationFault::inlet: case SimulationFault::drain: return 1;
            case SimulationFault::imbalance: case SimulationFault::door: return 2;
            case SimulationFault::leak: return 3;
        }
        return 0;
    }
    int simulation_fault_base_mission(SimulationFault fault) const {
        switch (fault) {
            case SimulationFault::inlet: return 13;
            case SimulationFault::drain: return 14;
            case SimulationFault::imbalance: return 17;
            case SimulationFault::door: return 16;
            case SimulationFault::leak: return 19;
        }
        return 13;
    }
    std::uint32_t next_simulation_random() {
        std::uint32_t value = simulation_rng_state_;
        value ^= value << 13u; value ^= value >> 17u; value ^= value << 5u;
        simulation_rng_state_ = value == 0u ? 0x6d2b79f5u : value;
        return simulation_rng_state_;
    }
    std::uint8_t simulation_required_manual_pages() const {
        std::uint8_t required = static_cast<std::uint8_t>(1u << 0u); // safety page is mandatory in every case
        for (int i = 0; i < kSimulationFaultCount; ++i) {
            const auto fault = static_cast<SimulationFault>(i);
            if (!simulation_has_fault(fault)) continue;
            required |= static_cast<std::uint8_t>(1u << static_cast<unsigned int>(simulation_fault_manual_page(fault)));
        }
        return required;
    }
    bool simulation_manual_complete() const {
        const std::uint8_t required = simulation_required_manual_pages();
        return (simulation_manual_read_mask_ & required) == required;
    }
    bool simulation_category_fixed(SimulationFault fault) const {
        switch (fault) {
            case SimulationFault::inlet: return inlet_hose_clear_ && inlet_filter_clean_;
            case SimulationFault::drain: return drain_hose_clear_ && pump_filter_clean_ && !pump_filter_open_ && !tray_placed_;
            case SimulationFault::imbalance: return load_balanced_;
            case SimulationFault::door: return !door_obstructed_;
            case SimulationFault::leak: return simulation_leak_secured_ && !tap_open_ && !wet_floor_;
        }
        return false;
    }
    bool simulation_faults_fixed() const {
        for (int i = 0; i < kSimulationFaultCount; ++i) {
            const auto fault = static_cast<SimulationFault>(i);
            if (simulation_has_fault(fault) && !simulation_category_fixed(fault)) return false;
        }
        return simulation_fault_mask_ != 0u;
    }
    void set_message(std::string value, int kind) { message_ = std::move(value); message_kind_ = kind; }
    int basket_icon(int index, int slot) const { return is_expert_mission(index) ? kExpertMissions[expert_index(index)].icons[clamp_int(slot,0,3)] : kBasketIcons[clamp_int(index,0,kMissionCount-1)][clamp_int(slot,0,3)]; }
    const WashRule &wash_rule(int index) const { return is_expert_mission(index) ? kExpertWashRules[expert_index(index)] : kWashRules[clamp_int(index,0,11)]; }
    bool is_wash_mission(int index) const { return index < 12 || is_expert_mission(index); }
    bool mission_is_completed(int index) const { return is_expert_mission(index) ? expert_completed_[static_cast<std::size_t>(expert_index(index))] : completed_[static_cast<std::size_t>(clamp_int(index,0,kMissionCount-1))]; }
    int mission_best_stars(int index) const { return is_expert_mission(index) ? expert_best_stars_[static_cast<std::size_t>(expert_index(index))] : best_stars_[static_cast<std::size_t>(clamp_int(index,0,kMissionCount-1))]; }
    void mark_mission_completed(int index, int stars) { if(is_expert_mission(index)){ const int i=expert_index(index); expert_completed_[static_cast<std::size_t>(i)]=true; expert_best_stars_[static_cast<std::size_t>(i)]=std::max(expert_best_stars_[static_cast<std::size_t>(i)],stars); } else { const int i=clamp_int(index,0,kMissionCount-1); completed_[static_cast<std::size_t>(i)]=true; best_stars_[static_cast<std::size_t>(i)]=std::max(best_stars_[static_cast<std::size_t>(i)],stars); } }
    const char *mission_title(int index) const { return is_expert_mission(index) ? kExpertMissionTitles[rendered_language(language_)][expert_index(index)] : kMissionTitles[rendered_language(language_)][clamp_int(index, 0, kMissionCount - 1)]; }
    const char *mission_summary(int index) const { return is_expert_mission(index) ? kExpertMissionSummaries[rendered_language(language_)][expert_index(index)] : kMissionSummaries[rendered_language(language_)][clamp_int(index, 0, kMissionCount - 1)]; }
    const char *mission_goal(int index) const { return is_expert_mission(index) ? kExpertMissionGoals[rendered_language(language_)][expert_index(index)] : kMissionGoals[rendered_language(language_)][clamp_int(index, 0, kMissionCount - 1)]; }
    const char *mission_load(int index) const { return is_expert_mission(index) ? kExpertMissionLoads[rendered_language(language_)][expert_index(index)] : kMissionLoads[rendered_language(language_)][clamp_int(index, 0, kMissionCount - 1)]; }
    const char *mission_duration(int index) const { return is_expert_mission(index) ? kExpertMissionDurations[rendered_language(language_)][expert_index(index)] : kMissionDurations[rendered_language(language_)][clamp_int(index, 0, kMissionCount - 1)]; }
    const char *fault_display_label(int index) const {
        const int language = rendered_language(language_);
        switch (index) {
            case 12: return kLocalizedFaultLabels[language][0];
            case 17: return kLocalizedFaultLabels[language][1];
            case 18: return kLocalizedFaultLabels[language][2];
            case 19: return kLocalizedFaultLabels[language][3];
            default: return kMissions[clamp_int(index, 0, kMissionCount - 1)].code;
        }
    }
    const char *program_name(int index) const {
        const int language = rendered_language(language_);
        const int program = clamp_int(index, 0, 7);
        if (is_expert_mission(selected_mission_) && expert_index(selected_mission_) < 4)
            return kExpertLogiPrograms[language][program];
        return kLocalizedPrograms[language][program];
    }
    int default_temperature_for_program(int index) const {
        const int program = clamp_int(index, 0, 7);
        if (is_expert_mission(selected_mission_) && expert_index(selected_mission_) < 4) {
            // The expert selector follows the eight LOGI PRO wash programs, not the generic demo order.
            static constexpr int logi_defaults[8] = {40, 40, 40, 40, 40, 40, 30, 30};
            return logi_defaults[program];
        }
        return kDefaultTemp[program];
    }
    bool program_has_heating(int index) const {
        if (is_expert_mission(selected_mission_) && expert_index(selected_mission_) < 4)
            return true; // LOGI PRO P-1..P-8 wash programs can be configured with thermal phases.
        return index != 5 && index != 6; // Generic Rinse / Spin have no bath temperature.
    }
    const char *difficulty_label(int index) const {
        if (is_expert_mission(index)) return expert_text(eu_difficulty);
        const char *value = kMissions[clamp_int(index, 0, kMissionCount - 1)].difficulty;
        const int level = std::strcmp(value, "AVANZADA") == 0 ? 2 : (std::strcmp(value, "INTERMEDIA") == 0 ? 1 : 0);
        return kDifficultyLabels[rendered_language(language_)][level];
    }
    int completed_count() const { return static_cast<int>(std::count(completed_.begin(), completed_.end(), true)); }
    int expert_completed_count() const { return static_cast<int>(std::count(expert_completed_.begin(), expert_completed_.end(), true)); }
    bool all_missions_complete() const { return completed_count() == kMissionCount; }
    bool all_expert_missions_complete() const { return expert_completed_count() == kExpertMissionCount; }
    int next_unlocked_mission() const { for (int i=0;i<kMissionCount;++i) if (!completed_[static_cast<std::size_t>(i)]) return i; return kMissionCount-1; }
    int next_unlocked_expert_mission() const { for (int i=0;i<kExpertMissionCount;++i) if (!expert_completed_[static_cast<std::size_t>(i)]) return i; return kExpertMissionCount-1; }
    bool mission_unlocked(int index) const { if(index < kMissionCount) return all_missions_complete() || index <= next_unlocked_mission(); return all_missions_complete() && expert_index(index) <= next_unlocked_expert_mission(); }
    bool any_progress() const { return resume_pending_save_ || completed_count() > 0 || expert_completed_count() > 0 || score_ > 0; }
    void return_to_mission_menu() {
        const bool was_expert = is_expert_mission(selected_mission_);
        const bool just_unlocked_expert = !was_expert && selected_mission_ == kMissionCount - 1 && all_missions_complete();
        if (!was_expert && selected_mission_ >= 0 && selected_mission_ < kMissionCount)
            normal_selected_mission_ = selected_mission_;
        screen_ = Screen::missions;
        previous_screen_ = Screen::missions;
        adjusting_ = false;
        running_ = false;
        care_label_open_ = false;
        if (all_missions_complete()) {
            // Expert missions are shown automatically once all 20 standard missions are complete.
            expert_mode_view_ = true;
            expert_selected_mission_ = next_unlocked_expert_mission();
            selected_mission_ = kMissionCount + expert_selected_mission_;
            set_message(just_unlocked_expert ? expert_text(eu_unlock_message) : expert_text(eu_machine_info), 0);
        } else {
            expert_mode_view_ = false;
            selected_mission_ = next_unlocked_mission();
            normal_selected_mission_ = selected_mission_;
            set_message(ui_text(UiText::msg_select_next), 0);
        }
    }

    void switch_mission_mode(bool to_expert) {
        if (!all_missions_complete()) { set_message(expert_text(eu_locked_hint),2); queue_sound(hui::audio::Cue::error); return; }
        if (to_expert == expert_mode_view_) { queue_sound(hui::audio::Cue::focus); return; }
        if (to_expert) {
            normal_selected_mission_ = clamp_int(selected_mission_,0,kMissionCount-1);
            selected_mission_ = kMissionCount + clamp_int(expert_selected_mission_,0,kExpertMissionCount-1);
            expert_mode_view_ = true;
            set_message(expert_text(eu_machine_info),0);
        } else {
            expert_selected_mission_ = is_expert_mission(selected_mission_) ? expert_index(selected_mission_) : expert_selected_mission_;
            selected_mission_ = clamp_int(normal_selected_mission_,0,kMissionCount-1);
            expert_mode_view_ = false;
            set_message(ui_text(UiText::unlock_all_desc),0);
        }
        queue_sound(hui::audio::Cue::tab);
    }
    bool save_option_enabled(int index) const {
        if (index == 0) return save_exists_ || any_progress();
        if (index == 1 || index == 2) return save_exists_;
        return index == 3;
    }
    const char *slot_state_label() const {
        if (progress_dirty_) return ui_text(UiText::unsaved_progress);
        return save_exists_ ? ui_text(UiText::slot_saved) : ui_text(UiText::slot_empty);
    }
    int loaded_count() const {
        unsigned int bits = load_mask_; int count = 0;
        while (bits) { count += static_cast<int>(bits & 1u); bits >>= 1u; }
        return count;
    }
    bool all_loaded(unsigned int mask) const { return (load_mask_ & mask) == mask; }
    bool any_wrong_item(unsigned int mask) const { return (load_mask_ & ~mask) != 0u; }
    int maximum_safe_load_temperature(const WashRule &rule) const {
        int maximum = 90;
        bool found_garment = false;
        for (int slot = 0; slot < 4; ++slot) {
            if ((rule.required_items & (1u << slot)) == 0u) continue;
            const GarmentCareSpec *spec = garment_care_spec(basket_icon(selected_mission_, slot));
            if (spec == nullptr) return -1;
            maximum = std::min(maximum, spec->temp);
            found_garment = true;
        }
        return found_garment ? maximum : 0;
    }
    bool needs_cycle_mission() const { return is_expert_mission(selected_mission_) || selected_mission_ <= 17; }

    void reset_mission(int index) {
        if (!simulation_active_ && !mission_unlocked(index)) { set_message(ui_text(UiText::mission_locked), 2); queue_sound(hui::audio::Cue::error); return; }
        selected_mission_ = clamp_int(index, 0, kTotalMissionCount - 1);
        expert_mode_view_ = is_expert_mission(selected_mission_);
        if (is_expert_mission(selected_mission_)) expert_selected_mission_ = expert_index(selected_mission_);
        else normal_selected_mission_ = selected_mission_;
        care_label_open_ = false;
        progress_dirty_ = !simulation_active_;
        screen_ = Screen::play;
        previous_screen_ = Screen::play;
        resume_pending_save_ = !simulation_active_;
        focus_id_ = 0;
        adjusting_ = false;
        age_ = 0.0f;
        errors_ = 0;
        hints_ = 0;
        load_mask_ = 0;
        program_ = 0;
        temperature_ = 40;
        spin_ = 1000;
        washer_on_ = false;
        plugged_ = true;
        tap_open_ = true;
        door_open_ = true;
        drawer_open_ = false;
        detergent_i_ = detergent_ii_ = softener_ = prewash_ = extra_rinse_ = false;
        service_open_ = false;
        running_ = false;
        fault_revealed_ = false;
        completed_this_run_ = false;
        inlet_hose_clear_ = inlet_filter_clean_ = drain_hose_clear_ = pump_filter_clean_ = true;
        pump_filter_open_ = tray_placed_ = false;
        transport_bolts_removed_ = feet_level_ = load_balanced_ = true;
        door_obstructed_ = drawer_dirty_ = gasket_dirty_ = mud_brushed_ = wet_floor_ = foam_problem_ = water_in_drum_ = false;
        cycle_elapsed_ = water_level_ = drum_phase_ = 0.0f;
        door_anim_ = 1.0f; drawer_anim_ = 0.0f;
        if (selected_mission_ == 0 || selected_mission_ == 10) prewash_ = false;
        if (selected_mission_ == 2 || selected_mission_ == 3 || selected_mission_ == 8) softener_ = false;
        switch (selected_mission_) {
            case 12: // oversudsing
                service_open_ = false; washer_on_ = true; door_open_ = false; load_mask_ = 0x3u;
                detergent_ii_ = true; foam_problem_ = true; water_in_drum_ = true; program_ = 0; temperature_ = 40; spin_ = 800; break;
            case 13: // E10 inlet fault
                service_open_ = true; washer_on_ = true; door_open_ = false; tap_open_ = false;
                inlet_hose_clear_ = false; inlet_filter_clean_ = false; fault_revealed_ = false; break;
            case 14: // E21 drain fault
                service_open_ = true; washer_on_ = true; door_open_ = false; load_mask_ = 0x3u;
                drain_hose_clear_ = false; pump_filter_clean_ = false; water_in_drum_ = true; break;
            case 15: // E50 installation / balance
                service_open_ = true; washer_on_ = true; door_open_ = false; load_mask_ = 0x3u;
                transport_bolts_removed_ = false; feet_level_ = false; load_balanced_ = false; program_ = 6; temperature_ = 0; spin_ = 1200; break;
            case 16: // E40 door obstruction
                service_open_ = true; washer_on_ = true; door_open_ = false; load_mask_ = 0x1u; door_obstructed_ = true; break;
            case 17: // no spin
                service_open_ = true; washer_on_ = true; door_open_ = false; load_mask_ = 0x3u;
                load_balanced_ = false; drain_hose_clear_ = false; program_ = 6; temperature_ = 0; spin_ = 1000; break;
            case 18: // preventive maintenance
                service_open_ = true; door_open_ = true; drawer_dirty_ = true; gasket_dirty_ = true; load_mask_ = 0; break;
            case 19: // leak safety
                service_open_ = true; washer_on_ = true; door_open_ = false; tap_open_ = true; wet_floor_ = true; break;
            default: break;
        }
        if (selected_mission_ == 12) focus_id_ = 11;                 // adjust programme to rinse
        else if (selected_mission_ >= 13 && selected_mission_ <= 17) focus_id_ = 10; // isolate first
        else if (selected_mission_ == 18) focus_id_ = 6;              // open detergent drawer for maintenance
        else if (selected_mission_ == 19) focus_id_ = 10;              // turn power off first
        else focus_id_ = 0;                                           // start with laundry basket
        if (is_expert_mission(selected_mission_)) {
            const int expert = expert_index(selected_mission_);
            const WashRule &rule = kExpertWashRules[expert];
            program_ = rule.program;
            spin_ = 1000;
            detergent_i_ = detergent_ii_ = softener_ = prewash_ = extra_rinse_ = false;
            if (expert == 0 || expert == 2 || expert == 4) load_balanced_ = false;
            if (expert == 1) spin_ = 1000; // must be reduced to the simulator's 800 rpm limit
            if (expert == 3) spin_ = 1000; // must be reduced to the simulator's 600 rpm limit
            if (expert == 4) { load_mask_ = 0x3u; focus_id_ = 0; service_open_ = false; }
        }
        if (is_wash_mission(selected_mission_)) temperature_ = wash_rule(selected_mission_).target_temp;
        set_message(mission_summary(selected_mission_), 0);
        queue_sound(hui::audio::Cue::open);
        if (autosave_ && !simulation_active_) save_progress(true);
    }

    void start_random_simulation_case() {
        ++simulation_case_number_;
        const std::uint32_t seed = static_cast<std::uint32_t>(clock_ * 1000003.0f) ^
                                   static_cast<std::uint32_t>(age_ * 65537.0f) ^
                                   (static_cast<std::uint32_t>(simulation_case_number_) * 0x9e3779b9u);
        simulation_rng_state_ = seed == 0u ? 0x6d2b79f5u : seed;
        std::array<int, kSimulationFaultCount> pool{};
        for (int i = 0; i < kSimulationFaultCount; ++i) pool[static_cast<std::size_t>(i)] = i;
        for (int i = kSimulationFaultCount - 1; i > 0; --i) {
            const int j = static_cast<int>(next_simulation_random() % static_cast<std::uint32_t>(i + 1));
            std::swap(pool[static_cast<std::size_t>(i)], pool[static_cast<std::size_t>(j)]);
        }
        simulation_fault_mask_ = 0;
        for (int i = 0; i < kSimulationFaultsPerCase; ++i) {
            const int fault = pool[static_cast<std::size_t>(i)];
            simulation_fault_order_[static_cast<std::size_t>(i)] = fault;
            simulation_fault_mask_ |= simulation_fault_bit(static_cast<SimulationFault>(fault));
        }
        if (!simulation_active_) {
            simulation_return_mission_ = selected_mission_;
            simulation_return_normal_selection_ = normal_selected_mission_;
            simulation_return_expert_selection_ = expert_selected_mission_;
            simulation_return_expert_mode_view_ = expert_mode_view_;
        }
        simulation_active_ = true;
        simulation_manual_view_ = false;
        simulation_manual_read_mask_ = 0;
        simulation_manual_page_elapsed_ = 0.0f;
        simulation_leak_secured_ = false;
        const auto first_fault = static_cast<SimulationFault>(simulation_fault_order_[0]);
        reset_mission(simulation_fault_base_mission(first_fault));

        // Keep the machine interactive, but derive every initial fault state from the randomized case.
        washer_on_ = true; plugged_ = true; door_open_ = false;
        tap_open_ = !simulation_has_fault(SimulationFault::inlet) || simulation_has_fault(SimulationFault::leak);
        load_mask_ = 0x3u; program_ = 6; temperature_ = 0; spin_ = 1000;
        service_open_ = true; focus_id_ = 10; fault_revealed_ = true;
        inlet_hose_clear_ = !simulation_has_fault(SimulationFault::inlet);
        inlet_filter_clean_ = !simulation_has_fault(SimulationFault::inlet);
        drain_hose_clear_ = !simulation_has_fault(SimulationFault::drain);
        pump_filter_clean_ = !simulation_has_fault(SimulationFault::drain);
        pump_filter_open_ = false; tray_placed_ = false;
        load_balanced_ = !simulation_has_fault(SimulationFault::imbalance);
        transport_bolts_removed_ = true; feet_level_ = true;
        door_obstructed_ = simulation_has_fault(SimulationFault::door);
        wet_floor_ = simulation_has_fault(SimulationFault::leak);
        running_ = false; water_in_drum_ = simulation_has_fault(SimulationFault::drain);
        progress_dirty_ = false; resume_pending_save_ = false;
        screen_ = Screen::play; previous_screen_ = Screen::play;
        set_message(sim_text(SimText::alarm_heading), 0);
        queue_sound(hui::audio::Cue::open);
    }

    void move_mission(int delta) {
        if (is_expert_mission(selected_mission_) || expert_mode_view_) {
            const int next = (expert_index(selected_mission_) + delta + kExpertMissionCount) % kExpertMissionCount;
            selected_mission_ = kMissionCount + next; expert_selected_mission_ = next;
        } else {
            if (!all_missions_complete()) { selected_mission_ = next_unlocked_mission(); return; }
            selected_mission_ = (selected_mission_ + delta + kMissionCount) % kMissionCount;
            normal_selected_mission_ = selected_mission_;
        }
        queue_sound(hui::audio::Cue::focus);
    }

    void handle_stick(const hui::InputFrame &input, float dt) {
        const float ax = input.stick_x;
        const float ay = input.stick_y;
        Direction candidate = Direction::none;
        const float threshold = stick_direction_ == Direction::none ? 0.42f : 0.29f;
        if (std::max(std::abs(ax), std::abs(ay)) >= threshold) {
            if (std::abs(ax) > std::abs(ay)) candidate = ax < 0.0f ? Direction::left : Direction::right;
            else candidate = ay < 0.0f ? Direction::up : Direction::down;
        }
        if (candidate == Direction::none) { stick_direction_ = Direction::none; stick_repeat_timer_ = 0.0f; return; }
        if (candidate != stick_direction_) {
            stick_direction_ = candidate; stick_repeat_timer_ = 0.30f; handle_navigation(candidate); return;
        }
        stick_repeat_timer_ -= dt;
        if (stick_repeat_timer_ <= 0.0f) { handle_navigation(candidate); stick_repeat_timer_ = 0.15f; }
    }

    bool target_visible(int id) const {
        if (id >= 0 && id <= 3) return screen_ == Screen::play;
        if (id >= 7 && id <= 9) return screen_ == Screen::play && drawer_open_;
        if (id >= 18 && id <= 31) return screen_ == Screen::play && service_open_;
        if (id == 32) return screen_ == Screen::play && service_open_ && simulation_active_ && wet_floor_;
        if (id == 17) return screen_ == Screen::play && !service_open_;
        return screen_ == Screen::play && (id == 5 || id == 6 || (id >= 10 && id <= 16));
    }
    FocusNode focus_node(int id) const {
        static constexpr float item_x[4] = {847,1135,1423,1711};
        static constexpr float service_x[3] = {892,1274,1656};
        if (id >= 0 && id <= 3) return {id, item_x[id], 365.0f};
        if (id == 5) return {id, 340.0f, 685.0f};
        if (id == 6) return {id, 214.0f, 278.0f};
        if (id >= 7 && id <= 9) return {id, 194.0f + static_cast<float>(id - 7) * 42.0f, 285.0f};
        if (id == 10) return {id, 536.0f, 268.0f};
        if (id == 11) return {id, 452.0f, 267.0f};
        if (id == 12) return {id, 318.0f, 323.0f};
        if (id == 13) return {id, 358.0f, 323.0f};
        if (id == 14) return {id, 398.0f, 323.0f};
        if (id == 15) return {id, 438.0f, 323.0f};
        if (id == 16) return {id, 352.0f, 933.0f};
        if (id == 17) return {id, 1710.0f, 921.0f};
        if (id >= 18 && id <= 32) {
            const int n = id - 18;
            return {id, service_x[n % 3], 441.0f + static_cast<float>(n / 3) * 101.0f};
        }
        return {id, 0, 0};
    }
    void handle_navigation(Direction direction) {
        if (direction == Direction::none) return;
        if (screen_ == Screen::title) {
            const int step = direction == Direction::up ? -1 : (direction == Direction::down ? 1 : 0);
            if (step != 0) {
                const int current = title_selection_;
                for (int attempt=0; attempt<6; ++attempt) {
                    title_selection_ = (title_selection_ + step + 6) % 6;
                    if (title_selection_ != 0 || save_exists_ || any_progress()) break;
                }
                if (title_selection_ != current) queue_sound(hui::audio::Cue::focus); else queue_sound(hui::audio::Cue::error);
            }
            return;
        }
        if (screen_ == Screen::missions) {
            if (expert_mode_view_ && all_missions_complete()) {
                const int local = expert_index(selected_mission_);
                const int row = local / 3, col = local % 3;
                int nr=row, nc=col;
                if(direction==Direction::left) nc=std::max(0,col-1);
                if(direction==Direction::right) nc=std::min(2,col+1);
                if(direction==Direction::up) nr=std::max(0,row-1);
                if(direction==Direction::down) nr=std::min(1,row+1);
                const int next=std::min(kExpertMissionCount-1,nr*3+nc);
                if(next!=local){ selected_mission_=kMissionCount+next; expert_selected_mission_=next; queue_sound(hui::audio::Cue::focus); }
                else queue_sound(hui::audio::Cue::error);
                return;
            }
            if (!all_missions_complete()) { selected_mission_ = next_unlocked_mission(); queue_sound(hui::audio::Cue::focus); return; }
            const int row = selected_mission_ / 4;
            const int col = selected_mission_ % 4;
            int new_row = row, new_col = col;
            if (direction == Direction::left) new_col = std::max(0, col - 1);
            if (direction == Direction::right) new_col = std::min(3, col + 1);
            if (direction == Direction::up) new_row = std::max(0, row - 1);
            if (direction == Direction::down) new_row = std::min(4, row + 1);
            const int next = new_row * 4 + new_col;
            if (next != selected_mission_) { selected_mission_ = next; normal_selected_mission_=selected_mission_; queue_sound(hui::audio::Cue::focus); }
            else queue_sound(hui::audio::Cue::error);
            return;
        }
        if (screen_ == Screen::settings) {
            if (direction == Direction::up) settings_selection_ = (settings_selection_ + 6) % 7;
            else if (direction == Direction::down) settings_selection_ = (settings_selection_ + 1) % 7;
            else if (direction == Direction::left || direction == Direction::right) adjust_setting(direction == Direction::right ? 1 : -1);
            queue_sound(hui::audio::Cue::focus); return;
        }
        if (screen_ == Screen::saves) {
            const int step = direction == Direction::up ? -1 : (direction == Direction::down ? 1 : 0);
            if (step != 0) {
                const int original = saves_selection_;
                for (int attempt=0; attempt<4; ++attempt) {
                    saves_selection_ = (saves_selection_ + step + 4) % 4;
                    if (save_option_enabled(saves_selection_)) break;
                }
                queue_sound(saves_selection_ != original ? hui::audio::Cue::focus : hui::audio::Cue::error);
            }
            return;
        }
        if (screen_ == Screen::confirm_delete || screen_ == Screen::confirm_new_game) {
            dialog_selection_ = 1 - dialog_selection_; queue_sound(hui::audio::Cue::focus); return;
        }
        if (screen_ == Screen::manual) {
            const int page_count = manual_page_count();
            if (direction == Direction::up || direction == Direction::left) manual_page_ = (manual_page_ + page_count - 1) % page_count;
            else manual_page_ = (manual_page_ + 1) % page_count;
            if (simulation_manual_view_) simulation_manual_page_elapsed_ = 0.0f;
            queue_sound(hui::audio::Cue::tab);
            return;
        }
        if (screen_ == Screen::result) {
            if (direction == Direction::left) move_mission(-1);
            if (direction == Direction::right) move_mission(1);
            return;
        }
        if (adjusting_) {
            if (direction == Direction::left || direction == Direction::right) adjust_selected(direction == Direction::right ? 1 : -1);
            else { adjusting_ = false; handle_spatial_navigation(direction); }
            return;
        }
        handle_spatial_navigation(direction);
    }
    void handle_spatial_navigation(Direction direction) {
        const FocusNode from = focus_node(focus_id_);
        int best_id = -1;
        float best_score = 1.0e9f;
        for (int candidate = 0; candidate <= 32; ++candidate) {
            if (candidate == focus_id_ || !target_visible(candidate)) continue;
            const FocusNode to = focus_node(candidate);
            const float dx = to.x - from.x;
            const float dy = to.y - from.y;
            float major = 0.0f, minor = 0.0f;
            if (direction == Direction::right) { if (dx <= 14.0f) continue; major = dx; minor = std::abs(dy); }
            if (direction == Direction::left)  { if (dx >= -14.0f) continue; major = -dx; minor = std::abs(dy); }
            if (direction == Direction::down)  { if (dy <= 14.0f) continue; major = dy; minor = std::abs(dx); }
            if (direction == Direction::up)    { if (dy >= -14.0f) continue; major = -dy; minor = std::abs(dx); }
            const float score = major + minor * 1.9f + minor * minor / (major + 40.0f);
            if (score < best_score) { best_score = score; best_id = candidate; }
        }
        if (best_id >= 0) { focus_id_ = best_id; queue_sound(hui::audio::Cue::focus); }
        else queue_sound(hui::audio::Cue::error);
    }

    void go_back() {
        if (screen_ == Screen::manual) { screen_ = previous_screen_; simulation_manual_view_ = false; queue_sound(hui::audio::Cue::modal_close); return; }
        if (screen_ == Screen::confirm_delete) { screen_ = Screen::saves; queue_sound(hui::audio::Cue::back); return; }
        if (screen_ == Screen::confirm_new_game) { screen_ = Screen::title; title_selection_ = 1; queue_sound(hui::audio::Cue::back); return; }
        if (screen_ == Screen::settings || screen_ == Screen::saves) {
            screen_ = Screen::title;
            title_selection_ = (save_exists_ || any_progress()) ? 0 : 1;
        care_label_open_ = false;
        care_label_slot_ = 0;
            queue_sound(hui::audio::Cue::back); return;
        }
        if (screen_ == Screen::play || screen_ == Screen::result) {
            if (simulation_active_) {
                selected_mission_ = clamp_int(simulation_return_mission_, 0, kTotalMissionCount - 1);
                normal_selected_mission_ = clamp_int(simulation_return_normal_selection_, 0, kMissionCount - 1);
                expert_selected_mission_ = clamp_int(simulation_return_expert_selection_, 0, kExpertMissionCount - 1);
                expert_mode_view_ = simulation_return_expert_mode_view_;
                simulation_active_ = false; simulation_manual_view_ = false; simulation_fault_mask_ = 0;
                simulation_manual_read_mask_ = 0; simulation_leak_secured_ = false;
                progress_dirty_ = false; resume_pending_save_ = false;
                screen_ = Screen::simulation; previous_screen_ = Screen::simulation;
                service_open_ = false; running_ = false; care_label_open_ = false;
                queue_sound(hui::audio::Cue::back); return;
            }
            resume_pending_save_ = !simulation_active_ && !mission_is_completed(selected_mission_);
            if (autosave_) save_progress(resume_pending_save_);
            return_to_mission_menu();
            queue_sound(hui::audio::Cue::back); return;
        }
        if (screen_ == Screen::simulation) { screen_ = Screen::title; title_selection_ = 5; queue_sound(hui::audio::Cue::back); return; }
        if (screen_ == Screen::missions) { screen_ = Screen::title; title_selection_ = 0; queue_sound(hui::audio::Cue::back); return; }
        queue_sound(hui::audio::Cue::back);
    }

    void activate() {
        if (screen_ == Screen::title) { activate_title(); return; }
        if (screen_ == Screen::missions) { reset_mission(selected_mission_); return; }
        if (screen_ == Screen::simulation) { start_random_simulation_case(); return; }
        if (screen_ == Screen::settings) { activate_settings(); return; }
        if (screen_ == Screen::saves) { activate_saves(); return; }
        if (screen_ == Screen::confirm_delete) { confirm_delete_action(); return; }
        if (screen_ == Screen::confirm_new_game) { confirm_new_game_action(); return; }
        if (screen_ == Screen::manual) { screen_ = previous_screen_; simulation_manual_view_ = false; queue_sound(hui::audio::Cue::modal_close); return; }
        if (screen_ == Screen::result) {
            if (simulation_active_) { start_random_simulation_case(); return; }
            return_to_mission_menu(); queue_sound(hui::audio::Cue::back); return;
        }
        if (adjusting_) { adjusting_ = false; queue_sound(hui::audio::Cue::select); return; }
        if (focus_id_ >= 0 && focus_id_ <= 3) { interact_basket(focus_id_); return; }
        switch (focus_id_) {
            case 5: interact_door(); break;
            case 6: drawer_open_ = !drawer_open_; queue_sound(drawer_open_ ? hui::audio::Cue::open : hui::audio::Cue::modal_close); set_message(drawer_open_ ? ui_text(UiText::msg_drawer_open) : ui_text(UiText::msg_drawer_closed), 0); break;
            case 7: detergent_i_ = !detergent_i_; queue_sound(hui::audio::Cue::toggle); set_message(detergent_i_ ? ui_text(UiText::msg_detergent_pre) : ui_text(UiText::msg_compartment_empty), 0); break;
            case 8: detergent_ii_ = !detergent_ii_; queue_sound(hui::audio::Cue::toggle); set_message(detergent_ii_ ? ui_text(UiText::msg_detergent_main) : ui_text(UiText::msg_compartment_ii_empty), 0); break;
            case 9: softener_ = !softener_; queue_sound(hui::audio::Cue::toggle); set_message(softener_ ? ui_text(UiText::msg_softener_on) : ui_text(UiText::msg_softener_off), 0); break;
            case 10:
                if (!plugged_) {
                    washer_on_ = false;
                    set_message(ui_text(UiText::msg_power_no_mains), 2);
                    queue_sound(hui::audio::Cue::error);
                } else if (running_) {
                    set_message(ui_text(UiText::msg_power_block), 3);
                    queue_sound(hui::audio::Cue::error);
                } else {
                    washer_on_ = !washer_on_;
                    queue_sound(hui::audio::Cue::toggle);
                    set_message(washer_on_ ? ui_text(UiText::msg_power_on) : ui_text(UiText::msg_power_off), 0);
                }
                break;
            case 11: case 12: case 13: adjusting_ = true; queue_sound(hui::audio::Cue::open); set_message(focus_id_ == 11 ? ui_text(UiText::msg_dial_hint) : focus_id_ == 12 ? ui_text(UiText::msg_temperature_hint) : ui_text(UiText::msg_spin_hint), 0); break;
            case 14: prewash_ = !prewash_; queue_sound(hui::audio::Cue::toggle); set_message(prewash_ ? ui_text(UiText::msg_prewash_on) : ui_text(UiText::msg_prewash_off), 0); break;
            case 15: extra_rinse_ = !extra_rinse_; queue_sound(hui::audio::Cue::toggle); set_message(extra_rinse_ ? ui_text(UiText::msg_rinse_on) : ui_text(UiText::msg_rinse_off), 0); break;
            case 16: start_cycle(); break;
            case 17: service_open_ = !service_open_; focus_id_ = service_open_ ? 18 : 17; queue_sound(service_open_ ? hui::audio::Cue::open : hui::audio::Cue::modal_close); set_message(service_open_ ? ui_text(UiText::msg_service_open) : ui_text(UiText::msg_service_closed), 0); break;
            case 18: service_plug(); break;
            case 19: tap_open_ = !tap_open_; queue_sound(hui::audio::Cue::toggle); set_message(tap_open_ ? ui_text(UiText::msg_tap_open) : ui_text(UiText::msg_tap_closed), 0); break;
            case 20: service_hose(true); break;
            case 21: service_inlet_filter(); break;
            case 22: service_hose(false); break;
            case 23: tray_placed_ = !tray_placed_; queue_sound(hui::audio::Cue::toggle); set_message(tray_placed_ ? ui_text(UiText::msg_tray_placed) : ui_text(UiText::msg_tray_removed), 0); break;
            case 24: service_pump_filter(); break;
            case 25: service_feet(); break;
            case 26: service_bolts(); break;
            case 27: service_balance(); break;
            case 28: service_obstruction(); break;
            case 29: service_clean_drawer(); break;
            case 30: service_clean_gasket(); break;
            case 31: service_brush_mud(); break;
            case 32: service_dry_floor(); break;
            default: break;
        }
        check_non_cycle_completion();
    }

    void interact_basket(int slot) {
        const unsigned int bit = 1u << static_cast<unsigned int>(slot);
        if (running_) { set_message(ui_text(UiText::msg_load_busy), 3); queue_sound(hui::audio::Cue::error); return; }
        if (!door_open_) { set_message(ui_text(UiText::msg_door_to_load), 2); queue_sound(hui::audio::Cue::error); return; }
        if ((load_mask_ & bit) != 0u) {
            load_mask_ &= ~bit;
            if (is_expert_mission(selected_mission_) && wash_rule(selected_mission_).require_balance) load_balanced_ = false;
            queue_sound(hui::audio::Cue::drop);
            set_message(std::string(localized_texture_label(basket_icon(selected_mission_,slot), selected_mission_, slot, language_)) + ui_text(UiText::msg_item_out_drum_suffix), 0);
        } else {
            if (loaded_count() >= 4) { set_message(ui_text(UiText::msg_drum_full), 3); queue_sound(hui::audio::Cue::error); return; }
            load_mask_ |= bit;
            if (is_expert_mission(selected_mission_) && wash_rule(selected_mission_).require_balance) load_balanced_ = false;
            queue_sound(hui::audio::Cue::pickup);
            set_message(std::string(localized_texture_label(basket_icon(selected_mission_,slot), selected_mission_, slot, language_)) + ui_text(UiText::msg_item_in_drum_suffix), 1);
        }
    }
    void interact_door() {
        if (running_ || (water_in_drum_ && (selected_mission_ == 14 || selected_mission_ == 12))) {
            set_message(ui_text(UiText::msg_door_locked), 2); queue_sound(hui::audio::Cue::error); return;
        }
        if (door_open_) {
            if (door_obstructed_) { set_message(ui_text(UiText::msg_door_obstacle), 2); queue_sound(hui::audio::Cue::error); return; }
            door_open_ = false;
            queue_sound(hui::audio::Cue::modal_close);
            set_message(ui_text(UiText::msg_door_closed), 1);
        } else {
            door_open_ = true; queue_sound(hui::audio::Cue::open); set_message(ui_text(UiText::msg_door_open), 0);
        }
    }

    void adjust_selected(int delta) {
        if (focus_id_ == 11) {
            program_ = (program_ + delta + 8) % 8;
            temperature_ = default_temperature_for_program(program_); spin_ = kDefaultSpin[program_];
            if (program_ > 3) prewash_ = false;
            queue_sound(hui::audio::Cue::rotate);
            set_message(std::string(ui_text(UiText::msg_program_prefix)) + program_name(program_) + ".", 0);
        } else if (focus_id_ == 12) {
            // 80 °C is a documented LOGI PRO P-1 phase in the supplied HS-6008 manual.
            static constexpr int temps[] = {0,20,30,40,60,80,90};
            int pos = 0; for (int i=0;i<7;++i) if (temps[i] == temperature_) pos = i;
            pos = (pos + delta + 7) % 7;
            temperature_ = program_has_heating(program_) ? temps[pos] : 0;
            queue_sound(hui::audio::Cue::slider);
            set_message(temperature_ == 0 ? ui_text(UiText::msg_no_heating) : std::string(ui_text(UiText::msg_temperature_prefix)) + format_int(temperature_) + " °C.", 0);
        } else if (focus_id_ == 13) {
            static constexpr int spins[] = {0,400,600,800,1000,1200};
            int pos = 0; for (int i=0;i<6;++i) if (spins[i] == spin_) pos = i;
            pos = (pos + delta + 6) % 6;
            spin_ = spins[pos];
            queue_sound(hui::audio::Cue::slider);
            set_message(std::string(ui_text(UiText::msg_spin_prefix)) + format_int(spin_) + " rpm.", 0);
        }
    }

    void enforce_power_invariant(bool show_feedback) {
        if (plugged_) return;
        const bool was_on = washer_on_;
        const bool was_running = running_;
        washer_on_ = false;
        // A stale save or unexpected disconnect must never leave an active cycle running.
        if (running_) {
            running_ = false;
            water_in_drum_ = true;
            water_level_ = std::max(water_level_, 0.12f);
        }
        if (!simulation_active_ && (was_on || was_running)) progress_dirty_ = true;
        if (show_feedback && (was_on || was_running)) {
            set_message(ui_text(UiText::msg_unplugged_poweroff), 2);
            queue_sound(hui::audio::Cue::error);
        }
    }
    void service_plug() {
        if (wet_floor_) {
            set_message(plugged_ ? ui_text(UiText::msg_wet_floor) : ui_text(UiText::msg_reconnect_wet_floor), 3);
            queue_sound(hui::audio::Cue::error); return;
        }
        const bool was_on = washer_on_;
        const bool was_running = running_;
        plugged_ = !plugged_;
        progress_dirty_ = !simulation_active_;
        if (!plugged_) {
            // A physical disconnection always removes power; if the drum was moving,
            // interrupt the cycle and retain residual water instead of lying about state.
            washer_on_ = false;
            if (was_running) {
                running_ = false;
                water_in_drum_ = true;
                water_level_ = std::max(water_level_, 0.12f);
                resume_pending_save_ = !mission_is_completed(selected_mission_);
                set_message(ui_text(UiText::msg_unplug_interrupted), 2);
                queue_sound(hui::audio::Cue::error);
            } else {
                set_message(was_on ? ui_text(UiText::msg_unplugged_poweroff) : ui_text(UiText::msg_unplugged_already_off), 0);
                queue_sound(hui::audio::Cue::toggle);
            }
        } else {
            // Reconnecting power does not switch a washer back on by itself.
            washer_on_ = false;
            set_message(ui_text(UiText::msg_plug_connected_manual), 0);
            queue_sound(hui::audio::Cue::toggle);
        }
    }
    bool service_isolated() const { return !washer_on_ && !plugged_; }
    void service_hose(bool inlet) {
        if (!service_isolated()) { set_message(ui_text(UiText::msg_service_hose_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        if (inlet) { inlet_hose_clear_ = true; queue_sound(hui::audio::Cue::connect); set_message(ui_text(UiText::msg_inlet_hose_clear), 1); }
        else { drain_hose_clear_ = true; queue_sound(hui::audio::Cue::connect); set_message(ui_text(UiText::msg_drain_hose_clear), 1); }
    }
    void service_inlet_filter() {
        if (!service_isolated() || tap_open_) { set_message(ui_text(UiText::msg_inlet_filter_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        inlet_filter_clean_ = true; queue_sound(hui::audio::Cue::solve); set_message(ui_text(UiText::msg_inlet_filter_clear), 1);
    }
    void service_pump_filter() {
        if (!service_isolated()) { set_message(ui_text(UiText::msg_pump_filter_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        if (!tray_placed_) { set_message(ui_text(UiText::msg_place_tray), 2); queue_sound(hui::audio::Cue::error); return; }
        if (!pump_filter_open_) { pump_filter_open_ = true; queue_sound(hui::audio::Cue::open); set_message(ui_text(UiText::msg_filter_open), 0); return; }
        if (!pump_filter_clean_) { pump_filter_clean_ = true; water_in_drum_ = false; queue_sound(hui::audio::Cue::pickup); set_message(ui_text(UiText::msg_debris_removed), 1); return; }
        pump_filter_open_ = false; tray_placed_ = false; queue_sound(hui::audio::Cue::modal_close); set_message(ui_text(UiText::msg_filter_closed), 1);
    }
    void service_feet() {
        if (!service_isolated()) { set_message(ui_text(UiText::msg_feet_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        feet_level_ = true; queue_sound(hui::audio::Cue::solve); set_message(ui_text(UiText::msg_feet_levelled), 1);
    }
    void service_bolts() {
        if (!service_isolated()) { set_message(ui_text(UiText::msg_bolts_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        transport_bolts_removed_ = true; queue_sound(hui::audio::Cue::pickup); set_message(ui_text(UiText::msg_bolts_removed), 1);
    }
    void service_balance() {
        if (washer_on_ || !door_open_) { set_message(ui_text(UiText::msg_balance_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        load_balanced_ = true; queue_sound(hui::audio::Cue::place); set_message(ui_text(UiText::msg_balance_done), 1);
    }
    void service_obstruction() {
        if (washer_on_ || !door_open_) { set_message(ui_text(UiText::msg_obstruction_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        door_obstructed_ = false; queue_sound(hui::audio::Cue::solve); set_message(ui_text(UiText::msg_obstruction_removed), 1);
    }
    void service_clean_drawer() {
        if (washer_on_ || !drawer_open_) { set_message(ui_text(UiText::msg_drawer_clean_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        drawer_dirty_ = false; detergent_i_ = detergent_ii_ = softener_ = false; queue_sound(hui::audio::Cue::solve); set_message(ui_text(UiText::msg_drawer_clean), 1);
    }
    void service_clean_gasket() {
        if (washer_on_ || !door_open_ || loaded_count() != 0) { set_message(ui_text(UiText::msg_gasket_clean_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        gasket_dirty_ = false; queue_sound(hui::audio::Cue::solve); set_message(ui_text(UiText::msg_gasket_clean), 1);
    }
    void service_brush_mud() {
        if (washer_on_ || !door_open_) { set_message(ui_text(UiText::msg_mud_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        mud_brushed_ = true; queue_sound(hui::audio::Cue::pickup); set_message(ui_text(UiText::msg_mud_removed), 1);
    }
    void service_dry_floor() {
        if (!simulation_active_ || !wet_floor_) return;
        if (washer_on_ || tap_open_) { set_message(sim_text(SimText::spill_safety), 3); queue_sound(hui::audio::Cue::error); return; }
        wet_floor_ = false;
        simulation_leak_secured_ = true;
        focus_id_ = plugged_ ? 18 : 19;
        queue_sound(hui::audio::Cue::solve);
        set_message(sim_text(SimText::spill_done), 1);
    }

    bool fault_fixed() const {
        switch (selected_mission_) {
            case 12: return program_ == 5 && extra_rinse_ && !detergent_ii_ && !detergent_i_;
            case 13: return tap_open_ && inlet_hose_clear_ && inlet_filter_clean_;
            case 14: return drain_hose_clear_ && pump_filter_clean_ && !pump_filter_open_ && !tray_placed_;
            case 15: return transport_bolts_removed_ && feet_level_ && load_balanced_;
            case 16: return !door_obstructed_;
            case 17: return load_balanced_ && drain_hose_clear_;
            default: return true;
        }
    }
    std::string validation_error() const {
        if (simulation_active_ && !simulation_faults_fixed()) return sim_text(SimText::alarm_active);
        if (simulation_active_ && !simulation_has_fault(SimulationFault::leak) && !tap_open_) return ui_text(UiText::err_open_tap);
        if (!plugged_) return ui_text(UiText::err_no_power);
        if (!washer_on_) return ui_text(UiText::err_power_button);
        if (!tap_open_ && selected_mission_ != 14) return ui_text(UiText::err_open_tap);
        if (door_open_) return ui_text(UiText::err_close_door);
        if (door_obstructed_) return ui_text(UiText::err_door_obstructed);
        if (pump_filter_open_ || tray_placed_) return ui_text(UiText::err_close_filter);
        if (is_wash_mission(selected_mission_)) {
            const WashRule &r = wash_rule(selected_mission_);
            if (!all_loaded(r.required_items)) return ui_text(UiText::err_missing_items);
            if (any_wrong_item(r.required_items)) return ui_text(UiText::err_wrong_items);
            if (program_ != r.program) return std::string(ui_text(UiText::msg_program_prefix)) + program_name(r.program) + ui_text(UiText::err_program_correct_suffix);
            const int safe_temperature = maximum_safe_load_temperature(r);
            if (safe_temperature < 0 || r.target_temp > safe_temperature || temperature_ > safe_temperature)
                return ui_text(UiText::err_temperature);
            if (temperature_ != r.target_temp) return ui_text(UiText::err_temperature);
            if (spin_ > r.max_spin) return ui_text(UiText::err_spin_too_high);
            if (r.requires_main_dose && !detergent_ii_) return ui_text(UiText::err_detergent_missing);
            if (r.require_balance && !load_balanced_) return expert_text(eu_balance_hint);
            if (r.prewash && (!prewash_ || !detergent_i_)) return ui_text(UiText::err_prewash_missing);
            if (!r.prewash && prewash_ && !detergent_i_) return ui_text(UiText::err_prewash_dose_missing);
            if (r.extra_rinse && !extra_rinse_) return ui_text(UiText::err_extra_rinse_missing);
            if (r.no_softener && softener_) return ui_text(UiText::err_softener_forbidden);
            if (r.no_detergent && (detergent_i_ || detergent_ii_)) return expert_text(eu_no_detergent_hint);
            if (r.brush_before_wash && !mud_brushed_) return ui_text(UiText::err_brush_before_wash);
        } else {
            if (!fault_fixed()) return std::string(ui_text(UiText::err_fault_active_prefix)) + (mission().code ? fault_display_label(selected_mission_) : ui_text(UiText::label_pump_filter)) + ui_text(UiText::err_fault_active_suffix);
            if (selected_mission_ == 12 && (program_ != 5 || !extra_rinse_ || detergent_ii_ || detergent_i_))
                return ui_text(UiText::err_foam_corrective);
            if (selected_mission_ == 17 && program_ != 6) return ui_text(UiText::err_spin_after_drain);
        }
        return {};
    }

    void start_cycle() {
        if (running_) { set_message(ui_text(UiText::msg_cycle_already_running), 2); queue_sound(hui::audio::Cue::error); return; }
        if (simulation_active_) {
            if (!simulation_manual_complete()) { ++errors_; set_message(sim_text(SimText::manual_required), 3); queue_sound(hui::audio::Cue::error); return; }
            if (!simulation_faults_fixed()) { ++errors_; set_message(sim_text(SimText::alarm_active), 3); queue_sound(hui::audio::Cue::error); return; }
            if (simulation_has_fault(SimulationFault::leak)) {
                set_message(sim_text(SimText::result_contained), 1);
                complete_mission();
                return;
            }
        }
        if (!is_expert_mission(selected_mission_) && selected_mission_ == 18) { set_message(ui_text(UiText::msg_maintenance_no_cycle), 0); queue_sound(hui::audio::Cue::notify); return; }
        if (!is_expert_mission(selected_mission_) && selected_mission_ == 19) { set_message(ui_text(UiText::msg_leak_no_cycle), 3); queue_sound(hui::audio::Cue::error); return; }
        if (!is_expert_mission(selected_mission_) && selected_mission_ >= 12 && selected_mission_ <= 17 && !fault_revealed_) {
            fault_revealed_ = true;
            set_message(std::string(ui_text(UiText::msg_fault_display_prefix)) + fault_display_label(selected_mission_) + ui_text(UiText::msg_fault_display_suffix), 2);
            queue_sound(hui::audio::Cue::notify); return;
        }
        const std::string issue = validation_error();
        if (!issue.empty()) {
            ++errors_; set_message(issue, 3); queue_sound(hui::audio::Cue::error); return;
        }
        running_ = true; completed_this_run_ = false; cycle_elapsed_ = 0.0f;
        cycle_duration_ = program_ == 4 ? 10.0f : (program_ == 5 || program_ == 6 ? 12.0f : 18.0f);
        water_in_drum_ = true; water_level_ = 0.08f; drum_phase_ = 0.0f;
        set_message(ui_text(UiText::msg_cycle_started), 1);
        queue_sound(hui::audio::Cue::launch);
    }
    void update_cycle(float dt) {
        if (!running_) {
            drum_phase_ += dt * 0.20f;
            water_level_ = approach(water_level_, water_in_drum_ ? 0.20f : 0.0f, dt * 0.08f);
            return;
        }
        cycle_elapsed_ += dt;
        const float t = clamp01(cycle_elapsed_ / cycle_duration_);
        const float spin_speed = (t > 0.78f) ? 11.0f : ((t > 0.25f && t < 0.60f) ? 2.6f : 0.8f);
        drum_phase_ += dt * spin_speed;
        float target_water = 0.0f;
        if (t < 0.18f) target_water = t / 0.18f * 0.62f;
        else if (t < 0.60f) target_water = 0.55f + std::sin(clock_ * 2.3f) * 0.035f;
        else if (t < 0.80f) target_water = 0.38f;
        else target_water = std::max(0.0f, (1.0f - t) * 1.5f);
        water_level_ = approach(water_level_, target_water, dt * 0.8f);
        if (cycle_elapsed_ >= cycle_duration_) {
            running_ = false; water_in_drum_ = false; water_level_ = 0.0f;
            completed_this_run_ = true;
            set_message(ui_text(UiText::msg_cycle_finished), 1);
            complete_mission();
        }
    }
    void complete_mission() {
        if (simulation_active_) {
            progress_dirty_ = false; resume_pending_save_ = false;
            screen_ = Screen::result; message_kind_ = 1;
            if (!simulation_has_fault(SimulationFault::leak)) set_message(sim_text(SimText::result_repaired), 1);
            else set_message(sim_text(SimText::result_contained), 1);
            queue_sound(hui::audio::Cue::complete);
            return;
        }
        if (mission_is_completed(selected_mission_) && mission_best_stars(selected_mission_) >= current_stars()) {
            resume_pending_save_ = false;
            screen_ = Screen::result; if (autosave_) save_progress(false); queue_sound(hui::audio::Cue::complete); return;
        }
        const int stars = current_stars();
        mark_mission_completed(selected_mission_, stars);
        progress_dirty_ = true;
        resume_pending_save_ = false;
        score_ += stars * 100 + (errors_ == 0 ? 30 : 0);
        screen_ = Screen::result;
        message_kind_ = 1;
        if (autosave_) save_progress(false);
        queue_sound(hui::audio::Cue::complete);
    }
    int current_stars() const { return errors_ == 0 && hints_ == 0 ? 3 : (errors_ <= 2 && hints_ <= 1 ? 2 : 1); }
    void check_non_cycle_completion() {
        if (screen_ != Screen::play || simulation_active_) return;
        if (selected_mission_ == 18 && !drawer_dirty_ && !gasket_dirty_ && loaded_count() == 0) {
            set_message(ui_text(UiText::msg_maintenance_finished), 1);
            complete_mission();
        } else if (selected_mission_ == 19 && !washer_on_ && !tap_open_) {
            set_message(ui_text(UiText::msg_area_secured), 1);
            complete_mission();
        }
    }
    void show_hint() {
        if (screen_ != Screen::play || simulation_active_) return;
        ++hints_;
        std::string hint;
        if (is_wash_mission(selected_mission_)) {
            const WashRule &r = wash_rule(selected_mission_);
            if (!all_loaded(r.required_items) || any_wrong_item(r.required_items)) hint = ui_text(UiText::hint_load_items);
            else if (program_ != r.program) hint = std::string(ui_text(UiText::hint_program_prefix)) + program_name(r.program) + ui_text(UiText::hint_program_suffix);
            else if (temperature_ != r.target_temp) hint = std::string(ui_text(UiText::hint_temperature_prefix)) + format_int(r.target_temp) + ui_text(UiText::hint_temperature_suffix);
            else if (r.require_balance && !load_balanced_) hint = expert_text(eu_balance_hint);
            else if (r.requires_main_dose && !detergent_ii_) hint = ui_text(UiText::hint_dose_ii);
            else if (r.prewash && (!prewash_ || !detergent_i_)) hint = ui_text(UiText::hint_prewash);
            else if (r.extra_rinse && !extra_rinse_) hint = ui_text(UiText::hint_extra_rinse);
            else if (r.brush_before_wash && !mud_brushed_) hint = ui_text(UiText::hint_brush_mud);
            else hint = ui_text(UiText::hint_finish_setup);
        } else if (selected_mission_ == 12) hint = ui_text(UiText::hint_foam);
        else if (selected_mission_ == 13) hint = ui_text(UiText::hint_inlet_fault);
        else if (selected_mission_ == 14) hint = ui_text(UiText::hint_drain_fault);
        else if (selected_mission_ == 15) hint = ui_text(UiText::hint_installation_fault);
        else if (selected_mission_ == 16) hint = ui_text(UiText::hint_door_fault);
        else if (selected_mission_ == 17) hint = ui_text(UiText::hint_spin_fault);
        else if (selected_mission_ == 18) hint = ui_text(UiText::hint_maintenance);
        else hint = ui_text(UiText::hint_leak);
        set_message(std::string(ui_text(UiText::hint_prefix)) + hint, 2);
        queue_sound(hui::audio::Cue::notify);
    }

