    static constexpr const char *kProgressPath = "/data/taller-colada-slot1.sav";
    static constexpr const char *kExpertProgressPath = "/data/taller-colada-expert-slot1.sav";
    static constexpr const char *kSettingsPath = "/data/taller-colada-settings.dat";
    static std::uint32_t hash_bytes(const void *bytes, std::size_t size) {
        const auto *p=static_cast<const unsigned char *>(bytes); std::uint32_t h=2166136261u;
        for(std::size_t i=0;i<size;++i){ h^=p[i]; h*=16777619u; }
        return h;
    }
    static bool write_blob(const char *path, const void *data, std::size_t size) {
        std::string temp(path); temp += ".tmp";
        std::FILE *f=std::fopen(temp.c_str(),"wb"); if(!f) return false;
        const bool ok=std::fwrite(data,1,size,f)==size && std::fflush(f)==0;
        const bool closed=std::fclose(f)==0;
        if(!ok||!closed){ ::remove(temp.c_str()); return false; }
        if(::rename(temp.c_str(),path)!=0){ ::remove(temp.c_str()); return false; }
        return true;
    }
    static bool read_blob(const char *path, void *data, std::size_t size) {
        std::FILE *f=std::fopen(path,"rb"); if(!f) return false;
        const bool ok=std::fread(data,1,size,f)==size && std::fgetc(f)==EOF;
        std::fclose(f); return ok;
    }
    static bool valid_save(const SaveSnapshot &d) {
        if(std::memcmp(d.magic,"TCLDSAV1",8)!=0 || d.version!=1u) return false;
        const auto offset=offsetof(SaveSnapshot,completed);
        return d.checksum==hash_bytes(reinterpret_cast<const unsigned char *>(&d)+offset,sizeof(SaveSnapshot)-offset);
    }
    static bool valid_expert_save(const ExpertSaveSnapshot &d) {
        if(std::memcmp(d.magic,"TCLDEXP1",8)!=0 || d.version!=1u) return false;
        const auto offset=offsetof(ExpertSaveSnapshot,completed);
        return d.checksum==hash_bytes(reinterpret_cast<const unsigned char *>(&d)+offset,sizeof(ExpertSaveSnapshot)-offset);
    }
    bool save_expert_progress() {
        ExpertSaveSnapshot d; std::memset(&d,0,sizeof(d));
        std::memcpy(d.magic,"TCLDEXP1",8); d.version=1u;
        for(int i=0;i<kExpertMissionCount;++i){ d.completed[i]=expert_completed_[static_cast<std::size_t>(i)]?1u:0u; d.stars[i]=static_cast<std::uint8_t>(clamp_int(expert_best_stars_[static_cast<std::size_t>(i)],0,3)); }
        const auto offset=offsetof(ExpertSaveSnapshot,completed);
        d.checksum=hash_bytes(reinterpret_cast<const unsigned char *>(&d)+offset,sizeof(ExpertSaveSnapshot)-offset);
        return write_blob(kExpertProgressPath,&d,sizeof(d));
    }
    void load_expert_progress() {
        expert_completed_.fill(false); expert_best_stars_.fill(0);
        ExpertSaveSnapshot d; std::memset(&d,0,sizeof(d));
        if(!read_blob(kExpertProgressPath,&d,sizeof(d)) || !valid_expert_save(d)) return; // Old save files have no expert sidecar.
        for(int i=0;i<kExpertMissionCount;++i){ expert_completed_[static_cast<std::size_t>(i)]=d.completed[i]!=0; expert_best_stars_[static_cast<std::size_t>(i)]=clamp_int(d.stars[i],0,3); }
    }
    static bool valid_settings(const SettingsSnapshot &d) {
        if(std::memcmp(d.magic,"TCLDSET1",8)!=0 || d.version!=1u) return false;
        const auto offset=offsetof(SettingsSnapshot,language);
        return d.checksum==hash_bytes(reinterpret_cast<const unsigned char *>(&d)+offset,sizeof(SettingsSnapshot)-offset);
    }
    void save_settings_to_disk() {
        SettingsSnapshot d; std::memset(&d,0,sizeof(d));
        std::memcpy(d.magic,"TCLDSET1",8); d.version=1u;
        d.language=static_cast<std::uint8_t>(clamp_int(language_,0,7));
        d.effects_volume=static_cast<std::uint8_t>(clamp_int(effects_volume_,0,100));
        d.brightness=static_cast<std::uint8_t>(clamp_int(brightness_,0,100));
        d.ui_scale=static_cast<std::uint8_t>(clamp_int(ui_scale_,80,100)); d.autosave=autosave_?1u:0u;
        const auto offset=offsetof(SettingsSnapshot,language);
        d.checksum=hash_bytes(reinterpret_cast<const unsigned char *>(&d)+offset,sizeof(SettingsSnapshot)-offset);
        write_blob(kSettingsPath,&d,sizeof(d));
    }
    void load_settings_from_disk() {
        SettingsSnapshot d; std::memset(&d,0,sizeof(d));
        if(!read_blob(kSettingsPath,&d,sizeof(d)) || !valid_settings(d)) return;
        language_=clamp_int(d.language,0,7); effects_volume_=clamp_int(d.effects_volume,0,100);
        brightness_=clamp_int(d.brightness,0,100); ui_scale_=(d.ui_scale>=80 && d.ui_scale<=100)?d.ui_scale:88; autosave_=d.autosave!=0;
    }
    void inspect_saved_game() {
        SaveSnapshot d; std::memset(&d,0,sizeof(d));
        save_exists_=read_blob(kProgressPath,&d,sizeof(d)) && valid_save(d);
        saved_completed_count_=0;
        if(save_exists_) for(int i=0;i<kMissionCount;++i) if(d.completed[i]) ++saved_completed_count_;
        save_status_=save_exists_?ui_text(UiText::slot_saved):ui_text(UiText::slot_empty);
    }
    void save_progress(bool resume_active) {
        SaveSnapshot d; std::memset(&d,0,sizeof(d));
        std::memcpy(d.magic,"TCLDSAV1",8); d.version=1u;
        for(int i=0;i<kMissionCount;++i){ d.completed[i]=completed_[static_cast<std::size_t>(i)]?1u:0u; d.stars[i]=static_cast<std::uint8_t>(clamp_int(best_stars_[static_cast<std::size_t>(i)],0,3)); }
        d.score=score_; d.selected_mission=selected_mission_; d.resume_active=resume_active?1u:0u;
        d.focus_id=focus_id_; d.load_mask=load_mask_; d.program=program_; d.temperature=temperature_; d.spin=spin_;
        const bool state[29]={washer_on_,plugged_,tap_open_,door_open_,drawer_open_,detergent_i_,detergent_ii_,softener_,prewash_,extra_rinse_,service_open_,inlet_hose_clear_,inlet_filter_clean_,drain_hose_clear_,pump_filter_clean_,pump_filter_open_,tray_placed_,transport_bolts_removed_,feet_level_,load_balanced_,door_obstructed_,drawer_dirty_,gasket_dirty_,mud_brushed_,wet_floor_,foam_problem_,water_in_drum_,fault_revealed_,running_};
        for(int i=0;i<29;++i) d.state[i]=state[i]?1u:0u;
        d.cycle_elapsed=cycle_elapsed_; d.cycle_duration=cycle_duration_; d.water_level=water_level_; d.drum_phase=drum_phase_;
        const auto offset=offsetof(SaveSnapshot,completed);
        d.checksum=hash_bytes(reinterpret_cast<const unsigned char *>(&d)+offset,sizeof(SaveSnapshot)-offset);
        const bool base_saved=write_blob(kProgressPath,&d,sizeof(d));
        const bool expert_saved=base_saved && save_expert_progress();
        save_exists_=base_saved;
        if(base_saved && expert_saved){
            saved_completed_count_=completed_count(); save_status_=ui_text(UiText::save_success); progress_dirty_=false;
        } else { save_status_=ui_text(UiText::save_failed); progress_dirty_=true; }
    }
    bool load_progress_from_disk() {
        SaveSnapshot d; std::memset(&d,0,sizeof(d));
        if(!read_blob(kProgressPath,&d,sizeof(d)) || !valid_save(d) || d.selected_mission<0 || d.selected_mission>=kTotalMissionCount) {
            save_exists_=false; save_status_=ui_text(UiText::load_failed); return false;
        }
        for(int i=0;i<kMissionCount;++i){ completed_[static_cast<std::size_t>(i)]=d.completed[i]!=0; best_stars_[static_cast<std::size_t>(i)]=clamp_int(d.stars[i],0,3); }
        load_expert_progress();
        score_=std::max(0,static_cast<int>(d.score)); selected_mission_=clamp_int(d.selected_mission,0,kTotalMissionCount-1);
        expert_mode_view_=is_expert_mission(selected_mission_);
        if(expert_mode_view_) {
            expert_selected_mission_=expert_index(selected_mission_);
            if(!all_missions_complete()) { selected_mission_=next_unlocked_mission(); expert_mode_view_=false; normal_selected_mission_=selected_mission_; }
            else if(expert_selected_mission_>next_unlocked_expert_mission()) { expert_selected_mission_=next_unlocked_expert_mission(); selected_mission_=kMissionCount+expert_selected_mission_; }
        } else normal_selected_mission_=selected_mission_;
        focus_id_=clamp_int(d.focus_id,0,31); load_mask_=d.load_mask&0x0fu; program_=clamp_int(d.program,0,7);
        temperature_=clamp_int(d.temperature,0,90); spin_=clamp_int(d.spin,0,1600);
        bool *state[29]={&washer_on_,&plugged_,&tap_open_,&door_open_,&drawer_open_,&detergent_i_,&detergent_ii_,&softener_,&prewash_,&extra_rinse_,&service_open_,&inlet_hose_clear_,&inlet_filter_clean_,&drain_hose_clear_,&pump_filter_clean_,&pump_filter_open_,&tray_placed_,&transport_bolts_removed_,&feet_level_,&load_balanced_,&door_obstructed_,&drawer_dirty_,&gasket_dirty_,&mud_brushed_,&wet_floor_,&foam_problem_,&water_in_drum_,&fault_revealed_,&running_};
        for(int i=0;i<29;++i) *state[i]=d.state[i]!=0;
        cycle_elapsed_=std::max(0.0f,std::min(d.cycle_elapsed,3600.0f)); cycle_duration_=std::max(1.0f,std::min(d.cycle_duration,3600.0f));
        const bool invalid_power_state = !plugged_ && (washer_on_ || running_);
        const bool interrupted_by_unplug = !plugged_ && running_;
        enforce_power_invariant(false);
        water_level_=clamp01(d.water_level); drum_phase_=std::fmod(std::max(0.0f,d.drum_phase),2.0f*kPi);
        door_anim_=door_open_?1.0f:0.0f; drawer_anim_=drawer_open_?1.0f:0.0f; adjusting_=false; pending_sound_=false;
        save_exists_=true; saved_completed_count_=completed_count(); progress_dirty_=invalid_power_state;
        resume_pending_save_ = d.resume_active!=0 && !mission_is_completed(selected_mission_);
        if(resume_pending_save_) {
            screen_=Screen::play; previous_screen_=Screen::play;
            set_message(interrupted_by_unplug ? ui_text(UiText::msg_unplug_interrupted) : (invalid_power_state ? ui_text(UiText::msg_unplugged_poweroff) : ui_text(UiText::load_success)), (interrupted_by_unplug || invalid_power_state) ? 2 : 1);
        } else {
            if(!all_missions_complete()) {
                selected_mission_=next_unlocked_mission(); normal_selected_mission_=selected_mission_; expert_mode_view_=false;
            } else {
                expert_mode_view_=true;
                expert_selected_mission_=next_unlocked_expert_mission();
                selected_mission_=kMissionCount+expert_selected_mission_;
            }
            screen_=Screen::missions; previous_screen_=Screen::missions; running_=false;
            set_message(interrupted_by_unplug ? ui_text(UiText::msg_unplug_interrupted) : (invalid_power_state ? ui_text(UiText::msg_unplugged_poweroff) : ui_text(UiText::load_success)), (interrupted_by_unplug || invalid_power_state) ? 2 : 1);
        }
        title_selection_=0; queue_sound(hui::audio::Cue::complete); return true;
    }
