    bool delete_progress_file() {
        const bool base_removed=(::remove(kProgressPath)==0 || !save_exists_);
        ::remove(kExpertProgressPath);
        if(base_removed){ clear_progress_memory(); save_status_=ui_text(UiText::delete_success); return true; }
        save_status_=ui_text(UiText::delete_failed); return false;
    }
    void begin_new_game() {
        // Do not erase in-memory progress unless an existing saved slot can be replaced safely.
        if (save_exists_ && !delete_progress_file()) {
            screen_ = Screen::title; title_selection_ = 1;
            set_message(ui_text(UiText::delete_failed), 3); queue_sound(hui::audio::Cue::error);
            return;
        }
        clear_progress_memory();
        screen_=Screen::missions; previous_screen_=Screen::missions;
        set_message(ui_text(UiText::mission_unlock_hint),0); queue_sound(hui::audio::Cue::select);
    }
    void continue_game() {
        if (save_exists_ && load_progress_from_disk()) return;
        if (!any_progress()) {
            screen_=Screen::title; title_selection_=1;
            set_message(ui_text(UiText::no_progress),2); queue_sound(hui::audio::Cue::error);
            return;
        }
        if (resume_pending_save_) {
            screen_=Screen::play; previous_screen_=Screen::play;
            set_message(ui_text(UiText::resume_mission),0); queue_sound(hui::audio::Cue::select);
            return;
        }
        selected_mission_=all_missions_complete()?selected_mission_:next_unlocked_mission();
        screen_=Screen::missions; previous_screen_=Screen::missions;
        set_message(ui_text(UiText::resume_mission),0); queue_sound(hui::audio::Cue::select);
    }
    void activate_title() {
        switch(title_selection_){
            case 0: continue_game(); break;
            case 1:
                if(any_progress()||save_exists_){ screen_=Screen::confirm_new_game; dialog_selection_=1; }
                else begin_new_game();
                break;
            case 2: screen_=Screen::saves; saves_selection_=0; queue_sound(hui::audio::Cue::open); break;
            case 3: screen_=Screen::settings; settings_selection_=0; queue_sound(hui::audio::Cue::open); break;
            case 4: previous_screen_=Screen::title; screen_=Screen::manual; manual_page_=0; queue_sound(hui::audio::Cue::modal_open); break;
            case 5: screen_=Screen::simulation; previous_screen_=Screen::simulation; queue_sound(hui::audio::Cue::open); break;
        }
    }
    void adjust_setting(int delta) {
        switch(settings_selection_){
            case 0: language_=(language_+delta+8)%8; break;
            case 1: effects_volume_=clamp_int(effects_volume_+delta*10,0,100); break;
            case 2: brightness_=clamp_int(brightness_+delta*5,0,100); break;
            case 3: ui_scale_=clamp_int(ui_scale_+delta*5,80,100); break;
            case 4: autosave_=!autosave_; break;
            default: break;
        }
        save_settings_to_disk(); queue_sound(hui::audio::Cue::toggle);
    }
    void activate_settings() {
        if(settings_selection_>=0 && settings_selection_<=4) adjust_setting(1);
        else if(settings_selection_==5){ language_=0; effects_volume_=70; brightness_=50; ui_scale_=88; autosave_=true; save_settings_to_disk(); set_message(ui_text(UiText::settings_reset),1); queue_sound(hui::audio::Cue::select); }
        else { screen_=Screen::title; title_selection_=3; queue_sound(hui::audio::Cue::back); }
    }
    void activate_saves() {
        if (!save_option_enabled(saves_selection_)) {
            set_message(ui_text(UiText::slot_empty),2); queue_sound(hui::audio::Cue::error); return;
        }
        if(saves_selection_==0){
            save_progress(resume_pending_save_);
            inspect_saved_game();
            set_message(save_status_,save_exists_?1:3);
            queue_sound(save_exists_?hui::audio::Cue::complete:hui::audio::Cue::error);
        } else if(saves_selection_==1){
            if(!load_progress_from_disk()){ set_message(ui_text(UiText::load_failed),3); queue_sound(hui::audio::Cue::error); }
        } else if(saves_selection_==2){
            screen_=Screen::confirm_delete; dialog_selection_=1;
        } else {
            screen_=Screen::title; title_selection_=(save_exists_ || any_progress()) ? 0 : 1;
            queue_sound(hui::audio::Cue::back);
        }
    }
    void confirm_delete_action() {
        if(dialog_selection_==0){ const bool ok=delete_progress_file(); set_message(save_status_,ok?1:3); screen_=Screen::saves; if(ok) { title_selection_=1; } }
        else screen_=Screen::saves;
        queue_sound(dialog_selection_==0?hui::audio::Cue::notify:hui::audio::Cue::back);
        saves_selection_=(dialog_selection_==0 && !save_exists_)?3:2;
    }
    void confirm_new_game_action() {
        if(dialog_selection_==0) begin_new_game(); else { screen_=Screen::title; title_selection_=1; }
        queue_sound(dialog_selection_==0?hui::audio::Cue::notify:hui::audio::Cue::back);
    }

    void load_textures() {
        if (textures_loaded_) return;
        textures_loaded_ = true;
        for (int i = 0; i < kIconCount; ++i) {
            if (i >= 2 && i <= 6) continue; // legacy garment resources remain in the manifest; their atlas cells are used instead.
            std::string bytes;
            const std::string path = std::string("/app0/assets/") + kTexturePaths[i];
            if (!hui::save::read_file(path, &bytes, 1048584) || bytes.size() < 8) continue;
            const auto *raw = reinterpret_cast<const unsigned char *>(bytes.data());
            const std::uint32_t width = static_cast<std::uint32_t>(raw[0]) | (static_cast<std::uint32_t>(raw[1]) << 8) | (static_cast<std::uint32_t>(raw[2]) << 16) | (static_cast<std::uint32_t>(raw[3]) << 24);
            const std::uint32_t height = static_cast<std::uint32_t>(raw[4]) | (static_cast<std::uint32_t>(raw[5]) << 8) | (static_cast<std::uint32_t>(raw[6]) << 16) | (static_cast<std::uint32_t>(raw[7]) << 24);
            if (width == 0 || height == 0 || width > 512 || height > 512 || bytes.size() != 8u + static_cast<std::size_t>(width) * height * 4u) continue;
            GLint old_texture = 0, old_alignment = 4;
            glGetIntegerv(GL_TEXTURE_BINDING_2D, &old_texture); glGetIntegerv(GL_UNPACK_ALIGNMENT, &old_alignment);
            glGenTextures(1, &textures_[static_cast<std::size_t>(i)]);
            if (textures_[static_cast<std::size_t>(i)] == 0) continue;
            glBindTexture(GL_TEXTURE_2D, textures_[static_cast<std::size_t>(i)]);
            glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR); glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE); glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
            glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, static_cast<GLsizei>(width), static_cast<GLsizei>(height), 0, GL_RGBA, GL_UNSIGNED_BYTE, bytes.data() + 8);
            glBindTexture(GL_TEXTURE_2D, static_cast<GLuint>(old_texture)); glPixelStorei(GL_UNPACK_ALIGNMENT, old_alignment);
        }
    }

    bool load_fallback_font_asset(const char *file_name, hui::gfx::Font &font,
                                  std::uint32_t *texture, std::string_view embedded_base64) const {
        if (texture == nullptr || *texture != 0) return texture != nullptr && *texture != 0;
        std::string bytes;
        const std::string path = std::string("/app0/assets/fonts/") + file_name;
        bool loaded = hui::save::read_file(path, &bytes, 4u << 20) && font.load(bytes);
        if (!loaded && !embedded_base64.empty()) {
            // Runtime-generated IDE workspaces may not carry loose .huifont files.
            bytes = decode_base64(embedded_base64);
            loaded = !bytes.empty() && font.load(bytes);
        }
        if (!loaded) {
            hui::sys::log("[TallerColada] fallback font %s could not be loaded from asset or embedded data (bytes=%u)",
                          file_name, static_cast<unsigned int>(bytes.size()));
            return false;
        }
        GLint old_active_texture = GL_TEXTURE0;
        glGetIntegerv(GL_ACTIVE_TEXTURE, &old_active_texture);
        glActiveTexture(GL_TEXTURE0);
        GLint old_texture = 0, old_alignment = 4;
        glGetIntegerv(GL_TEXTURE_BINDING_2D, &old_texture);
        glGetIntegerv(GL_UNPACK_ALIGNMENT, &old_alignment);
        GLuint created = 0;
        glGenTextures(1, &created);
        if (created == 0) {
            glPixelStorei(GL_UNPACK_ALIGNMENT, old_alignment);
            glBindTexture(GL_TEXTURE_2D, static_cast<GLuint>(old_texture));
            glActiveTexture(static_cast<GLenum>(old_active_texture));
            hui::sys::log("[TallerColada] could not allocate texture for fallback font %s", file_name);
            return false;
        }
        glBindTexture(GL_TEXTURE_2D, created);
        glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_R8, font.atlas_width(), font.atlas_height(), 0,
                     GL_RED, GL_UNSIGNED_BYTE, font.atlas().data());
        // Match the renderer's font texture setup: a single SDF atlas, no mip chain.
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAX_LEVEL, 0);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
        glBindTexture(GL_TEXTURE_2D, static_cast<GLuint>(old_texture));
        glPixelStorei(GL_UNPACK_ALIGNMENT, old_alignment);
        glActiveTexture(static_cast<GLenum>(old_active_texture));
        *texture = created;
        return true;
    }

    void ensure_language_fallbacks() const {
        const int lang = rendered_language(language_);
        if (active_font_language_ == lang) return;

        // Use assets bundled with this title rather than relying on fields added
        // only in newer Visual-PS5 template versions. This keeps the generated
        // screen portable while ensuring accents and CJK glyphs actually render.
        if (!latin_fallback_attempted_) {
            latin_fallback_attempted_ = true;
            load_fallback_font_asset("inter-latin-fallback.huifont", latin_fallback_font_,
                                     &latin_fallback_texture_, kEmbeddedLatinFontBase64);
        }
        if (lang == 5 && !japanese_fallback_attempted_) {
            japanese_fallback_attempted_ = true;
            load_fallback_font_asset("noto-sans-jp-cjk.huifont", cjk_japanese_fallback_font_,
                                     &cjk_japanese_fallback_texture_, kEmbeddedJapaneseFontBase64);
        }
        if (lang == 6 && !chinese_fallback_attempted_) {
            chinese_fallback_attempted_ = true;
            load_fallback_font_asset("noto-sans-sc-cjk.huifont", cjk_chinese_fallback_font_,
                                     &cjk_chinese_fallback_texture_, kEmbeddedChineseFontBase64);
        }

        const hui::gfx::Font *cjk_face = nullptr;
        std::uint32_t cjk_texture = 0;
        if (lang == 5 && cjk_japanese_fallback_texture_ != 0) {
            cjk_face = &cjk_japanese_fallback_font_;
            cjk_texture = cjk_japanese_fallback_texture_;
        } else if (lang == 6 && cjk_chinese_fallback_texture_ != 0) {
            cjk_face = &cjk_chinese_fallback_font_;
            cjk_texture = cjk_chinese_fallback_texture_;
        }
        const auto apply = [this, cjk_face, cjk_texture](const hui::ui::FontRef &ref) {
            if (!ref.font) return;
            auto *font = const_cast<hui::gfx::Font *>(ref.font);
            font->clear_fallbacks();
            if (latin_fallback_texture_ != 0)
                font->add_fallback(&latin_fallback_font_, latin_fallback_texture_);
            if (cjk_face != nullptr && cjk_texture != 0)
                font->add_fallback(cjk_face, cjk_texture);
        };
        apply(context_.fonts.regular);
        apply(context_.fonts.semibold);
        apply(context_.fonts.display);
        active_font_language_ = lang;
    }

    std::string renderable_text(std::string_view value, const hui::ui::FontRef &font) const {
        // Never transliterate accented letters or drop Japanese/Chinese silently.
        // Localization validation and the build-time CJK font baker guarantee glyph coverage.
        (void)font;
        return std::string(value);
    }

    void text(DrawList &draw, std::string_view value, float x, float y, float size, Color color, bool bold = false, bool centered = false) const {
        const hui::ui::FontRef &font = bold ? context_.fonts.semibold : context_.fonts.regular;
        const std::string str = renderable_text(value,font);
        if (centered) hui::ui::text(draw,font,str,x,y,size,color,hui::gfx::Align::center);
        else hui::ui::text(draw,font,str,x,y,size,color);
    }
    void fitted_text(DrawList &draw, std::string_view value, float x, float y, float size, Color color, float max_width, bool bold = false, bool centered = false) const {
        const hui::ui::FontRef &font = bold ? context_.fonts.semibold : context_.fonts.regular;
        const std::string clean = renderable_text(value,font);
        const std::string fit = renderable_text(font.font->fit(clean,size,max_width),font);
        if (centered) hui::ui::text(draw,font,fit,x,y,size,color,hui::gfx::Align::center);
        else hui::ui::text(draw,font,fit,x,y,size,color);
    }
    void wrapped_text(DrawList &draw, std::string_view value, float x, float y, float size, Color color, int max_chars, int max_lines, bool bold = false) const {
        const hui::ui::FontRef &font = bold ? context_.fonts.semibold : context_.fonts.regular;
        const std::string clean = renderable_text(value,font);
        const float nominal_width = static_cast<float>(std::max(max_chars,4)) * size * 0.54f;
        const float screen_width = std::max(size*4.0f,1920.0f-x-42.0f);
        const float max_width = std::min(nominal_width,screen_width);
        std::vector<std::string> lines = font.font->wrap(clean,size,max_width);
        if (lines.empty()) lines.emplace_back();
        const std::size_t cap=static_cast<std::size_t>(std::max(max_lines,1));
        if (lines.size()>cap) {
            lines.resize(cap);
            lines.back()=font.font->fit(lines.back()+"...",size,max_width);
        }
        const float line_height=std::max(size+5.0f,font.font->line_height(size)+2.0f);
        for (std::size_t i=0;i<lines.size();++i) text(draw,lines[i],x,y+static_cast<float>(i)*line_height,size,color,bold);
    }
    void wrapped_text_box(DrawList &draw, std::string_view value, Rect box, float size, Color color,
                          int max_lines, bool bold = false, bool centered = false) const {
        const hui::ui::FontRef &font = bold ? context_.fonts.semibold : context_.fonts.regular;
        const std::string clean = renderable_text(value,font);
        std::vector<std::string> lines = font.font->wrap(clean,size,std::max(size*4.0f,box.w));
        if (lines.empty()) lines.emplace_back();
        const float line_height=std::max(size+4.0f,font.font->line_height(size)+1.0f);
        const int vertical_cap=box.h>0.0f?std::max(1,static_cast<int>((box.h+1.0f)/line_height)):max_lines;
        const std::size_t cap=static_cast<std::size_t>(std::max(1,std::min(max_lines,vertical_cap)));
        if (lines.size()>cap) {
            lines.resize(cap);
            lines.back()=font.font->fit(lines.back()+"...",size,box.w);
        }
        for (std::size_t i=0;i<lines.size();++i) {
            const float x=centered?box.x+box.w*0.5f:box.x;
            text(draw,lines[i],x,box.y+static_cast<float>(i)*line_height,size,color,bold,centered);
        }
    }
    void right_text(DrawList &draw, std::string_view value, float right_edge, float y, float size, Color color, bool bold=false) const {
        const hui::ui::FontRef &font = bold ? context_.fonts.semibold : context_.fonts.regular;
        const std::string clean = renderable_text(value,font);
        hui::ui::text(draw,font,clean,right_edge,y,size,color,hui::gfx::Align::right);
    }
