    int garment_atlas_index(int item) const {
        if (item >= 1 && item <= 6) return item - 1;
        if (item >= 16 && item <= 24) return 6 + (item - 16);
        return -1;
    }
    // Draw a manifest texture by resource ID without interpreting the ID as a garment.
    // Keep this separate from image(): garment IDs 1..6 and 16..24 share the atlas namespace,
    // while technical parts must always use their own resource or dedicated vector icon.
    void image_resource(DrawList &draw, int resource, Rect rect) const {
        if (resource < 0 || resource >= kIconCount || textures_[static_cast<std::size_t>(resource)] == 0) {
            draw.rounded_rect(rect, 12, Color::rgb(0xdceaf2));
            return;
        }
        draw.image(textures_[static_cast<std::size_t>(resource)], rect, Rect{0,0,1,1}, Color::rgb(0xffffff), 9.0f);
    }
    void simulation_atlas_icon(DrawList &draw, int fault, bool fixed, Rect rect) const {
        if (fault < 0 || fault >= kSimulationFaultCount || textures_[kSimulationAtlasResource] == 0) return;
        constexpr float atlas_width = 640.0f, atlas_height = 256.0f, cell = 128.0f, inset = 2.0f;
        const int index = fault + (fixed ? kSimulationFaultCount : 0);
        const float u = (static_cast<float>(index % kSimulationFaultCount) * cell + inset) / atlas_width;
        const float v = (static_cast<float>(index / kSimulationFaultCount) * cell + inset) / atlas_height;
        const float span_u = (cell - inset * 2.0f) / atlas_width;
        const float span_v = (cell - inset * 2.0f) / atlas_height;
        draw.image(textures_[kSimulationAtlasResource], rect, Rect{u,v,span_u,span_v}, Color::rgb(0xffffff), 12.0f);
    }
    void image(DrawList &draw, int texture, Rect rect) const {
        const int atlas_index = garment_atlas_index(texture);
        if (atlas_index >= 0 && textures_[1] != 0) {
            // Safe atlas sampling: each sprite is packed with 18 px of clear padding.
            // Inset the UV rectangle by 2 texels so GL_LINEAR never samples a neighbor
            // if the driver evaluates a quad edge between adjacent atlas cells.
            constexpr float kAtlasSize = 512.0f;
            constexpr float kAtlasCellSize = 128.0f;
            constexpr float kAtlasUvInset = 2.0f;
            const float u = (static_cast<float>(atlas_index % 4) * kAtlasCellSize + kAtlasUvInset) / kAtlasSize;
            const float v = (static_cast<float>(atlas_index / 4) * kAtlasCellSize + kAtlasUvInset) / kAtlasSize;
            const float span = (kAtlasCellSize - 2.0f * kAtlasUvInset) / kAtlasSize;
            draw.image(textures_[1], rect, Rect{u, v, span, span}, Color::rgb(0xffffff), 9.0f);
            return;
        }
        if (texture == 0) {
            constexpr float kMachineAspect = 340.0f / 512.0f;
            float w = rect.w, h = rect.h;
            if (w / h > kMachineAspect) w = h * kMachineAspect;
            else h = w / kMachineAspect;
            image_resource(draw, 0, Rect{rect.x + (rect.w - w) * 0.5f, rect.y + (rect.h - h) * 0.5f, w, h});
            return;
        }
        image_resource(draw, texture, rect);
    }
    // Technical-zone icon indices are semantic categories, never garment/texture IDs.
    // Existing assets are used where they match; missing components are drawn as vector glyphs.
    void draw_technical_icon(DrawList &draw, int part, Rect r) const {
        const float cx = r.x + r.w * 0.5f;
        const float cy = r.y + r.h * 0.5f;
        switch (part) {
            case 0: image_resource(draw, 14, r); return; // power plug
            case 1: image_resource(draw, 9, r); return;  // water tap
            case 2: image_resource(draw, 10, r); return; // inlet hose (generic hose artwork)
            case 3: { // inlet filter / mesh strainer
                draw.rounded_rect(Rect{r.x+9,r.y+9,r.w-18,r.h-18},8,Color::rgb(0x708795));
                draw.rounded_rect(Rect{r.x+14,r.y+13,r.w-28,r.h-26},5,Color::rgb(0xdceaf0));
                for (int row=0; row<3; ++row) for (int col=0; col<4; ++col)
                    draw.circle(r.x+20+static_cast<float>(col)*5.5f,r.y+20+static_cast<float>(row)*6.0f,1.45f,Color::rgb(0x657e8c));
                draw.line(r.x+11, r.y+15, r.x+17, r.y+10, 2.0f, Color::rgb(0xa9bbc5));
                return;
            }
            case 4: image_resource(draw, 10, r); return; // drain hose
            case 5: { // drip tray
                draw.rounded_rect(Rect{r.x+5,r.y+16,r.w-10,r.h-21},7,Color::rgb(0x8ea5b2));
                draw.rounded_rect(Rect{r.x+9,r.y+19,r.w-18,r.h-27},5,Color::rgb(0xe8f1f5));
                draw.line(r.x+14,r.y+r.h-12,r.x+r.w-14,r.y+r.h-12,2.4f,Color::rgb(0x2a9bc0));
                draw.circle(r.x+r.w*0.34f,r.y+r.h*0.57f,2.0f,Color::rgb(0x5bb5d2));
                draw.circle(r.x+r.w*0.58f,r.y+r.h*0.62f,1.7f,Color::rgb(0x5bb5d2));
                return;
            }
            case 6: image_resource(draw, 11, r); return; // pump filter
            case 7: image_resource(draw, 12, r); return; // leveling foot
            case 8: image_resource(draw, 13, r); return; // transit bolts
            case 9: { // load balance / spirit level
                draw.rounded_rect(Rect{r.x+4,r.y+18,r.w-8,21},7,Color::rgb(0x718b99));
                draw.rounded_rect(Rect{r.x+8,r.y+22,r.w-16,13},4,Color::rgb(0xe7f1f5));
                draw.line(r.x+13,cy,r.x+r.w-13,cy,1.7f,Color::rgb(0x45a778));
                draw.circle(cx,cy,4.8f,Color::rgb(0x5f8fa1));
                draw.circle(cx,cy,2.6f,Color::rgb(0xd9f5e4));
                return;
            }
            case 10: { // door lock
                draw.circle(cx, r.y+21, 13, Color::rgb(0x718b99));
                draw.circle(cx, r.y+21, 7.5f, Color::rgb(0xe8f1f5));
                draw.rounded_rect(Rect{cx-17,r.y+21,34,27},6,Color::rgb(0x2a9bc0));
                draw.circle(cx,r.y+32,3.1f,Color::rgb(0xeaf7fc));
                draw.rounded_rect(Rect{cx-1.3f,r.y+33,2.6f,7},1.3f,Color::rgb(0xeaf7fc));
                return;
            }
            case 11: { // detergent drawer
                draw.rounded_rect(Rect{r.x+4,r.y+11,r.w-8,r.h-17},7,Color::rgb(0x91a7b3));
                draw.rounded_rect(Rect{r.x+8,r.y+15,r.w-16,r.h-25},4,Color::rgb(0xeaf2f6));
                draw.line(cx,r.y+16,cx,r.y+r.h-13,1.7f,Color::rgb(0x8ba0ad));
                draw.line(r.x+15,r.y+29,r.x+r.w-15,r.y+29,1.7f,Color::rgb(0x8ba0ad));
                draw.rounded_rect(Rect{cx-7,r.y+r.h-17,14,3.2f},1.5f,Color::rgb(0x637c8b));
                return;
            }
            case 12: { // door gasket / rubber seal
                draw.circle(cx,cy,23,Color::rgb(0x8497a3));
                draw.circle(cx,cy,18,Color::rgb(0x344b59));
                draw.circle(cx,cy,13,Color::rgb(0xb8d1dc));
                draw.circle(cx,cy,8,Color::rgb(0xe8f3f7));
                draw.circle(cx+13,cy-12,2.2f,Color::rgb(0x526d7b));
                return;
            }
            case 13: { // mud / dried soil, never a garment sprite
                draw.rounded_rect(Rect{r.x+5,r.y+34,r.w-10,12},6,Color::rgb(0x8e6242));
                draw.circle(r.x+17,r.y+30,9,Color::rgb(0x9e704c));
                draw.circle(r.x+28,r.y+23,10,Color::rgb(0x785035));
                draw.circle(r.x+39,r.y+31,8,Color::rgb(0xa97b54));
                draw.circle(r.x+25,r.y+36,5,Color::rgb(0x62412e));
                return;
            }
            case 14: simulation_atlas_icon(draw,4,simulation_category_fixed(SimulationFault::leak),r); return;
            default:
                draw.rounded_rect(r, 10, Color::rgb(0xdceaf2));
                return;
        }
    }
