        int clothing_count=0;
        for (int i=0;i<4;++i) if ((load_mask_ & (1u<<static_cast<unsigned int>(i)))!=0u) ++clothing_count;
        if (clothing_count==0) {
            text(draw,ui_text(UiText::empty_drum),cx,cy+7,12,Color::rgb(0xb5c7d0),true,true);
        } else {
            int shown=0;
            for (int i=0;i<4;++i) {
                if ((load_mask_ & (1u<<static_cast<unsigned int>(i)))==0u) continue;
                const float angle=drum_phase_+static_cast<float>(shown)*2.0f*kPi/static_cast<float>(clothing_count)-0.6f;
                const float radius=running_?36.0f:32.0f;
                const float size=running_?39.0f:36.0f;
                const float x=cx+std::cos(angle)*radius-size*0.5f;
                const float y=cy+std::sin(angle)*radius-size*0.5f;
                draw.push_transform(1.0f,x+size*0.5f,y+size*0.5f,0.0f,0.0f);
                image(draw,basket_icon(selected_mission_,i),Rect{x,y,size,size});
                draw.pop_transform(); ++shown;
            }
        }
        // Soft glass reflection; its transform continues to follow the open/closed door state.
        draw.push_transform(1.0f-0.18f*door_anim_,cx,cy,115.0f*door_anim_,-25.0f*door_anim_);
        draw.circle(cx,cy,91,Color::rgb(0xb1d8e6,0.26f));
        draw.circle(cx-22,cy-35,32,Color::rgb(0xffffff,0.10f));
        draw.circle(cx,cy,91,Color::rgb(0xffffff,0.08f));
        draw.pop_transform();
        draw.rounded_rect(Rect{152,863,411,30},10,Color::rgb(0xe8eef2));
        text(draw,ui_text(UiText::label_feet),205,883,10,kMuted,true,true);
        text(draw,ui_text(UiText::label_pump_filter),502,883,10,kMuted,true,true);
        image(draw,12,Rect{246,855,31,36}); image(draw,11,Rect{530,854,34,34});
        const int id=focus_id_;
        if (id==5) focus_outline(draw,Rect{cx-145,cy-135,290,270});
        else if (id==6) focus_outline(draw,Rect{148,239,143,62});
        else if (id>=7&&id<=9&&drawer_open_) focus_outline(draw,Rect{173.0f+drawer_anim_*2.0f+static_cast<float>(id-7)*42.0f,260.0f+drawer_anim_*5.0f,38,40});
        else if (id==10) focus_outline(draw,Rect{508,240,56,56});
        else if (id==11) focus_outline(draw,Rect{421,236,62,62});
        else if (id>=12&&id<=15) focus_outline(draw,Rect{static_cast<float>(bx_for_focus(id)),302,36,39});
        else if (id==16) focus_outline(draw,Rect{165,918,385,30});
    }
