    const char *cycle_stage() const {
        if (!running_) return ui_text(UiText::stage_waiting);
        const float t=cycle_elapsed_/cycle_duration_;
        if (t<0.17f) return ui_text(UiText::stage_filling);
        if (t<0.35f && prewash_) return ui_text(UiText::stage_prewash);
        if (t<0.57f) return ui_text(UiText::stage_washing);
        if (t<0.77f) return ui_text(UiText::stage_rinsing);
        if (t<0.88f) return ui_text(UiText::stage_draining);
        return ui_text(UiText::stage_spinning);
    }
