    bool service_priority(int id) const {
        if (simulation_active_) return false;
        switch (selected_mission_) {
            case 13: return id==18 || id==19 || id==20 || id==21;
            case 14: return id==18 || id==19 || id==22 || id==23 || id==24;
            case 15: return id==18 || id==25 || id==26 || id==27;
            case 16: return id==18 || id==28;
            case 17: return id==18 || id==22 || id==25 || id==27;
            case 18: return id==18 || id==29 || id==30;
            case 19: return id==19;
            default: return false;
        }
    }

