    void move_care_label_slot(int delta) {
        for (int attempt=0;attempt<4;++attempt) {
            care_label_slot_=(care_label_slot_+delta+4)%4;
            if (is_garment_texture(selected_care_texture())) { queue_sound(hui::audio::Cue::focus); return; }
        }
        queue_sound(hui::audio::Cue::error);
    }
    void open_care_label() {
        if (selected_mission_ >= 12 && !is_expert_mission(selected_mission_)) { set_message(ui_text(UiText::care_label_wash_only),2); queue_sound(hui::audio::Cue::error); return; }
        int preferred=(focus_id_>=0 && focus_id_<=3)?focus_id_:0;
        int slot=preferred;
        if (!is_garment_texture(basket_icon(selected_mission_,slot))) {
            bool found=false;
            for (int i=0;i<4;++i) if (is_garment_texture(basket_icon(selected_mission_,i))) { slot=i; found=true; break; }
            if (!found) { set_message(ui_text(UiText::care_label_select_item),2); queue_sound(hui::audio::Cue::error); return; }
        }
        care_label_slot_=slot; care_label_open_=true; queue_sound(hui::audio::Cue::modal_open);
    }
