        wrapped_text_box(draw,ui_text(UiText::care_original_label_reminder),Rect{438,780,1080,38},12,kBlue,2,true,false);
    }

    void draw_result(DrawList &draw) const {
        if (simulation_active_) {
            draw.rounded_rect(Rect{0,0,1920,1080},0,Color::rgb(0x173044,0.48f));
            const Rect card{390,220,1140,640};
            panel(draw,card,0xffffff,0xbdd6e2,32);
            draw.circle(960,322,62,Color::rgb(0xdff4e8));
            draw.circle(960,322,45,Color::rgb(0x1f7a4d));
            draw.line(941,322,956,337,6,Color::rgb(0xffffff));
            draw.line(956,337,981,307,6,Color::rgb(0xffffff));
            fitted_text(draw,sim_text(SimText::result_title),960,423,28,kInk,1000,true,true);
            wrapped_text_box(draw,sim_text(simulation_has_fault(SimulationFault::leak)?SimText::result_contained:SimText::result_repaired),Rect{570,470,780,72},16,kMuted,3,false,true);
            for (int i=0;i<kSimulationFaultsPerCase;++i) {
                const int fault=simulation_fault_order_[static_cast<std::size_t>(i)];
                const float x=480.0f+static_cast<float>(i)*242.0f;
                simulation_atlas_icon(draw,fault,true,Rect{x,575,72,72});
                fitted_text(draw,simulation_alarm_code(fault),x+84,614,14,kBlue,145,true);
            }
            draw.rounded_rect(Rect{645,724,630,60},15,Color::rgb(0x1b5f98));
            text(draw,sim_text(SimText::new_case),960,755,17,Color::rgb(0xffffff),true,true);
            return;
        }
        draw.rounded_rect(Rect{0,0,1920,1080},0,Color::rgb(0x173044,0.48f));
        const float pulse=1.0f+0.035f*std::sin(clock_*4.0f);
        const Rect card{545,240,830,580};
        draw.push_transform(pulse,960,530,0,0);
        panel(draw,card,0xffffff,0xbdd6e2,32);
        draw.circle(960,343,78,Color::rgb(0xdff4e8));
        draw.circle(960,343,59,Color::rgb(0x1f7a4d));
        // A drawn check, not a Unicode checkmark missing from some font atlases.
        draw.line(932,343,951,361,7,Color::rgb(0xffffff));
        draw.line(951,361,988,321,7,Color::rgb(0xffffff));
        text(draw,ui_text(UiText::mission_complete),960,462,32,kInk,true,true);
        wrapped_text(draw,mission_title(selected_mission_),725,500,19,kMuted,50,2,true);
        for (int i=0;i<3;++i) {
            const float x=890+i*70.0f;
            const bool lit=i<mission_best_stars(selected_mission_);
            draw.circle(x,571,25,Color::rgb(lit?0xf6c85e:0xe4edf2));
            draw.circle(x,571,16,Color::rgb(lit?0xffe6a0:0xf8fbfc));
            draw.circle(x,571,7,Color::rgb(lit?0xe0a030:0xd2dfe6));
        }
        const bool expert=is_expert_mission(selected_mission_);
        text(draw,std::string(ui_text(UiText::points))+" "+format_int(score_)+"     "+std::string(ui_text(UiText::completed))+" "+format_int(expert?expert_completed_count():completed_count())+(expert?" / 5":" / 20"),960,635,16,kBlue,true,true);
        wrapped_text(draw,mission_goal(selected_mission_),730,682,17,kMuted,64,2);
        draw.rounded_rect(Rect{735,744,450,54},15,Color::rgb(0x1b5f98));
        text(draw,ui_text(UiText::return_missions),960,778,16,Color::rgb(0xffffff),true,true);
        draw.pop_transform();
        if(all_missions_complete() && !expert && selected_mission_ == kMissionCount-1) {
            draw.rounded_rect(Rect{490,832,940,42},12,Color::rgb(0xfff2d5));
            draw.bordered_rect(Rect{490,832,940,42},12,Color::rgb(0xfff2d5),1.2f,Color::rgb(0xe0a030));
            fitted_text(draw,expert_text(eu_unlock_message),960,858,14,Color::rgb(0x875b0c),870,true,true);
        }
        const float px=700.0f+std::fmod(clock_*165.0f,500.0f);
        draw.circle(px,270+std::sin(clock_*2.0f)*25.0f,4,Color::rgb(0x2a9bc0,0.8f));
        draw.circle(1220-std::fmod(clock_*123.0f,480.0f),790,5,Color::rgb(0xe0a030,0.8f));
    }

    int manual_page_count() const { return simulation_manual_view_?kSimulationManualPageCount:6; }
    const char *manual_title(int page) const {
        return simulation_manual_view_?kSimulationManualTitles[rendered_language(language_)][clamp_int(page,0,kSimulationManualPageCount-1)]:kManualTitles[rendered_language(language_)][clamp_int(page,0,5)];
    }
    const char *manual_body(int page) const {
        return simulation_manual_view_?kSimulationManualPages[rendered_language(language_)][clamp_int(page,0,kSimulationManualPageCount-1)]:kManualPages[rendered_language(language_)][clamp_int(page,0,5)];
    }
    void draw_manual(DrawList &draw) const {
        draw.rounded_rect(Rect{0,0,1920,1080},0,Color::rgb(0x132d40,0.40f));
        panel(draw,Rect{315,200,1290,680},0xffffff,0xbfd4df,30);
        draw.rounded_rect(Rect{350,235,10,68},5,Color::rgb(0x2a9bc0));
        text(draw,simulation_manual_view_?sim_text(SimText::manual):ui_text(UiText::manual_heading),383,263,15,kBlue,true);
        text(draw,manual_title(manual_page_),383,324,28,kInk,true);
        const int page_count=manual_page_count();
        text(draw,std::string(ui_text(UiText::manual_section))+" "+format_int(manual_page_+1)+" / "+format_int(page_count),1535,324,13,kMuted,true,true);
        if (simulation_manual_view_) {
            wrapped_text_box(draw,manual_body(manual_page_),Rect{383,380,1128,350},18,Color::rgb(0x2e4a5b),10,false,false);
            if (simulation_active_) text(draw,sim_text((simulation_manual_read_mask_&(1u<<static_cast<unsigned int>(manual_page_)))!=0u?SimText::manual_read:SimText::manual_unread),383,759,12,kBlue,true);
        } else {
            wrapped_text(draw,manual_body(manual_page_),383,393,21,Color::rgb(0x2e4a5b),79,8);
        }
        const float indicators_x=960.0f-static_cast<float>(page_count)*36.5f;
        for (int i=0;i<page_count;++i) draw.rounded_rect(Rect{indicators_x+i*73.0f,778,56,8},4,Color::rgb(i==manual_page_?0x2a9bc0:0xd5e4ec));
        const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::manual_change_page)},{hui::ui::Button::cross,ui_text(UiText::manual_close)},{hui::ui::Button::circle,ui_text(UiText::back)}};
        hui::ui::HintLayout layout; layout.size=31; layout.text_size=20; layout.cy=835; layout.item_gap=30;
        hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,383,false,layout);
    }

    void draw_footer(DrawList &draw) const {
        draw.line(40,975,1880,975,1,Color::rgb(0xc8dbe5));
        if (screen_ == Screen::play && care_label_open_) {
            const hui::ui::Hint hints[]={{hui::ui::Button::right_stick,ui_text(UiText::care_label_close)},{hui::ui::Button::left_stick,ui_text(UiText::browse_garments)},{hui::ui::Button::circle,ui_text(UiText::back)}};
            hui::ui::HintLayout layout; layout.size=29; layout.text_size=17; layout.cy=1017; layout.item_gap=28;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,530,false,layout);
            return;
        }
        if (screen_ == Screen::title) {
            const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::navigate)},{hui::ui::Button::cross,ui_text(UiText::select)},{hui::ui::Button::triangle,ui_text(UiText::manual)}};
            hui::ui::HintLayout layout; layout.size=30; layout.text_size=19; layout.cy=1017; layout.item_gap=32;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,65,false,layout);
        } else if (screen_ == Screen::simulation) {
            const hui::ui::Hint hints[]={{hui::ui::Button::cross,sim_text(SimText::start)},{hui::ui::Button::triangle,sim_text(SimText::manual)},{hui::ui::Button::circle,sim_text(SimText::back)}};
            hui::ui::HintLayout layout; layout.size=28; layout.text_size=17; layout.cy=1017; layout.item_gap=28;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,65,false,layout);
        } else if (screen_ == Screen::missions) {
            if(all_missions_complete()) {
                if(expert_mode_view_) {
                    const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::navigate)},{hui::ui::Button::cross,ui_text(UiText::start_mission)},{hui::ui::Button::square,expert_text(eu_exit_hint)},{hui::ui::Button::circle,ui_text(UiText::back)}};
                    hui::ui::HintLayout layout; layout.size=25; layout.text_size=14; layout.cy=1017; layout.item_gap=17;
                    hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,4,65,false,layout);
                } else {
                    const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::navigate)},{hui::ui::Button::cross,ui_text(UiText::start_mission)},{hui::ui::Button::square,expert_text(eu_enter_hint)},{hui::ui::Button::circle,ui_text(UiText::back)}};
                    hui::ui::HintLayout layout; layout.size=25; layout.text_size=14; layout.cy=1017; layout.item_gap=17;
                    hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,4,65,false,layout);
                }
            } else {
                const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::navigate)},{hui::ui::Button::cross,ui_text(UiText::start_mission)},{hui::ui::Button::circle,ui_text(UiText::back)}};
                hui::ui::HintLayout layout; layout.size=30; layout.text_size=19; layout.cy=1017; layout.item_gap=32;
                hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,65,false,layout);
            }
        } else if (screen_ == Screen::settings || screen_ == Screen::saves || screen_ == Screen::confirm_delete || screen_ == Screen::confirm_new_game) {
            const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::navigate)},{hui::ui::Button::cross,ui_text(UiText::select)},{hui::ui::Button::circle,ui_text(UiText::back)}};
            hui::ui::HintLayout layout; layout.size=30; layout.text_size=19; layout.cy=1017; layout.item_gap=32;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,65,false,layout);
        } else if (screen_ == Screen::manual) {
            const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::manual_change_page)},{hui::ui::Button::cross,simulation_manual_view_?sim_text(SimText::back):ui_text(UiText::manual_close)},{hui::ui::Button::circle,ui_text(UiText::back)}};
            hui::ui::HintLayout layout; layout.size=29; layout.text_size=18; layout.cy=1017; layout.item_gap=30;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,3,65,false,layout);
        } else if (screen_ == Screen::result) {
            const hui::ui::Hint hints[]={{hui::ui::Button::cross,simulation_active_?sim_text(SimText::new_case):ui_text(UiText::return_missions)},{hui::ui::Button::circle,simulation_active_?sim_text(SimText::back):ui_text(UiText::back)}};
            hui::ui::HintLayout layout; layout.size=30; layout.text_size=19; layout.cy=1017; layout.item_gap=34;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,2,65,false,layout);
