            const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,ui_text(UiText::navigate)},{hui::ui::Button::cross,ui_text(UiText::interact)},{hui::ui::Button::triangle,sim_text(SimText::manual)},{hui::ui::Button::circle,sim_text(SimText::back)},{hui::ui::Button::options,ui_text(UiText::technical_zone)}};
            hui::ui::HintLayout layout; layout.size=26; layout.text_size=15; layout.cy=1017; layout.item_gap=20;
            hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,5,65,false,layout);
        } else {
            if (selected_mission_ < 12 || is_expert_mission(selected_mission_)) {
                const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,adjusting_?ui_text(UiText::adjust_short):ui_text(UiText::navigate)},{hui::ui::Button::cross,adjusting_?ui_text(UiText::accept):ui_text(UiText::interact)},{hui::ui::Button::square,ui_text(UiText::hint_short)},{hui::ui::Button::right_stick,ui_text(UiText::care_label)},{hui::ui::Button::triangle,ui_text(UiText::manual)},{hui::ui::Button::circle,ui_text(UiText::back)},{hui::ui::Button::options,ui_text(UiText::technical_zone)}};
                hui::ui::HintLayout layout; layout.size=24; layout.text_size=15; layout.cy=1017; layout.item_gap=14;
                hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,7,38,false,layout);
            } else {
                const hui::ui::Hint hints[]={{hui::ui::Button::left_stick,adjusting_?ui_text(UiText::adjust_short):ui_text(UiText::navigate)},{hui::ui::Button::cross,adjusting_?ui_text(UiText::accept):ui_text(UiText::interact)},{hui::ui::Button::square,ui_text(UiText::hint_short)},{hui::ui::Button::triangle,ui_text(UiText::manual)},{hui::ui::Button::circle,ui_text(UiText::back)},{hui::ui::Button::options,ui_text(UiText::technical_zone)}};
                hui::ui::HintLayout layout; layout.size=25; layout.text_size=16; layout.cy=1017; layout.item_gap=22;
                hui::ui::draw_hints(draw,context_.fonts,hui::ui::GlyphStyle::light(),hints,6,170,false,layout);
            }
        }
    }
